      open_menu = {
        ST = {
          ["1"] = {
            e = {
              {
                args = {
                  "0827144910BRXMZ AdventureMaster menu"
                },
                id = "document_show"
              }
            },
            t = "list"
          }
        }
      },
      runscript = {
        ST = {
          ["1"] = {
            e = {
              {
                args = {
                  "--[[Debugger (Don't Copy)]]\n--effect,getVar,setVar,op,args = function (...)end\n\n\n--[[Requirements]] --\n--用于处理表格和储存值的函数\nlocal winditup = \"FALSE\"\n---@v 1.0.23\nOctopus = {\n    logic = {\n        axis_square = function(axis, x1, y1, x2, y2)\n\n\n        end,\n        conclude = function(table, obj) --是否有此值\n\n            for i, v in pairs(table) do\n\n                if v == obj then\n                    return true\n                end\n\n            end\n\n            return false\n\n\n\n        end,\n        haskey = function(table, key) --是否有此键\n            for i, v in pairs(table) do\n                if tostring(key) == tostring(i) then\n                    return true\n                end\n\n            end\n            return false\n\n\n        end,\n        allset = function(table, value)\n\n            for i, v in pairs(table) do\n                if type(i) == \"table\" then\n                    Octopus.logic.allset(table, value)\n                else\n                    table[i] = value\n                end\n            end\n\n            return table\n\n        end,\n        isEmpty = function(tbl)\n            if next(tbl) ~= nil then\n                return false\n            else\n                return true\n            end\n        end,\n        ---@param tb table\n        tostring = function(tb)\n\n            --禁止使用以下字符：\" [ ] $ ^\n\n            local str = \"{\"\n\n            for i, v in pairs(tb) do\n\n                if type(v) == \"string\" then\n\n                    str = str .. \"[\" .. tostring(i) .. \"] = \" .. \"$\" .. v .. \"^\" .. \",\"\n\n                elseif type(v) == \"table\" then\n\n                    str = str .. \"[\" .. tostring(i) .. \"] = \" .. Octopus.logic.tostring(v) .. \",\"\n\n                else\n\n                    str = str .. \"[\" .. tostring(i) .. \"] = \" .. \"$\" .. tostring(v) .. \"^\" .. \",\"\n                end\n\n            end\n\n            str = str .. \"}\"\n\n            return str\n\n            --[[\n                [key] = $value$\n            ]]\n\n\n\n        end,\n\n        strtotable = function(tstring, runargs)\n\n            local function wordstotable(str) --将字符串拆开，每个字符表内的一个元素。\n                local i = 0\n                local tbl = {}\n                while i <= string.len(str) do\n                    i = i + 1\n                    local tmp = string.sub(str, i, i)\n                    tbl[i] = tmp\n\n                end\n                return tbl\n            end\n\n            tstring = string.sub(tstring, 2, tstring.len(tstring) - 1)\n\n            local onkeytyping = false\n            local onvaluetyping = false\n            local onmorestrtyping = false\n\n            local tbl = {}\n\n            local count_key = 0\n\n            local tempkey = \"\"\n\n            local tempfield = \"\"\n\n            local sontableamount = 0\n\n            if type(runargs) == \"nil\" then\n                runargs = {\n\n                    tablelevel = 1,\n                    tableamount = 0,\n\n                }\n            end\n\n            local level = \"【第 \" .. tostring(runargs[\"tablelevel\"]) .. \" 层】\"\n\n            --Logger.log(level..\"开始处理，要处理的字符串：\"..tstring)\n\n\n\n\n\n            for i, v in pairs(wordstotable(tstring)) do\n\n                --Logger.log(level..\"一次新循环，onkeytyping = \"..tostring(onkeytyping)..\"|| onvaluetyping = \"..tostring(onvaluetyping)..\"|| onmorestrtyping = \"..tostring(onmorestrtyping)..\"|| count_key = \"..tostring(count_key)..\"|| tempfield = \"..tempfield..\"|| 已有发现子表数量 = \" ..tostring(sontableamount))\n\n                if tostring(v) == \"{\" then\n\n                    if sontableamount == 0 and onvaluetyping == false then\n\n\n\n                        onmorestrtyping = true\n\n                        --Logger.log(level..\"开始处理一个表中表\")\n\n                    end\n\n                end\n\n\n\n\n                if onkeytyping == false or onvaluetyping == false or onmorestrtyping == false then\n\n\n                    if tostring(v) == \"[\" and onmorestrtyping == false then\n\n                        if count_key == 0 then\n\n                            --Logger.log(level..\"开始处理一个键\")\n\n                            onkeytyping = true\n\n                        end\n\n\n\n\n                    elseif tostring(v) == \"$\" and onmorestrtyping == false then\n\n                        --Logger.log(level..\"开始处理一个值\")\n\n                        onvaluetyping = true\n\n                    end\n\n                end\n                if onkeytyping == true and onvaluetyping == false and onmorestrtyping == false then\n\n                    if tostring(v) == \"]\" then\n\n                        tbl[tempfield] = \"NOVALUE\"\n\n                        --Logger.log(level..\"已完成储存一个键：\"..tempfield)\n\n                        count_key = count_key + 1\n\n                        --Logger.log(level..\"现有的键数量：\"..tostring(count_key))\n\n                        tempkey = tempfield\n\n                        --Logger.log(level..\"临时的键值：\"..tempkey)\n\n                        tempfield = \"\"\n\n                        --Logger.log(level..\"（键）tempfield清零\")\n\n                        onkeytyping = false\n\n                    else\n                        if tostring(v) ~= \"[\" then\n\n                            tempfield = tempfield .. tostring(v)\n                            --Logger.log(level..\"（键）tempfield被写为\"..tempfield)\n                        end\n                    end\n                end\n\n                if onvaluetyping == true and onkeytyping == false and onmorestrtyping == false then\n\n                    if tostring(v) == \"^\" then\n\n                        tbl[tempkey] = tempfield\n\n                        --Logger.log(level..\"已完成储存一个值：\"..tempfield)\n\n                        count_key = count_key - 1\n\n                        --Logger.log(level..\"现有的键数量：\"..tostring(count_key))\n\n                        tempkey = \"\"\n\n                        tempfield = \"\"\n\n                        --Logger.log(level..\"（值）tempfield清零\")\n\n                        onvaluetyping = false\n\n                    else\n\n                        if tostring(v) ~= \"$\" then\n\n\n\n                            tempfield = tempfield .. tostring(v)\n                            --Logger.log(level..\"（值）tempfield被写为\"..tempfield)\n                        end\n                    end\n                end\n\n\n\n\n                if onmorestrtyping == true then\n\n\n\n\n\n                    if tostring(v) == \"{\" then\n                        sontableamount = sontableamount + 1\n\n                        tempfield = tempfield .. tostring(v)\n                    end\n\n\n\n                    if tostring(v) == \"}\" then\n\n                        --Logger.log(level..\"}处理中，目前有子表：\"..tostring(sontableamount))\n\n\n                        if tonumber(sontableamount) == 1 then\n\n\n\n                            tempfield = tempfield .. tostring(v)\n\n                            runargs[\"tablelevel\"] = runargs[\"tablelevel\"] + 1\n\n\n\n\n                            local temptable = Octopus.logic.strtotable(tempfield, runargs)\n\n                            runargs[\"tablelevel\"] = runargs[\"tablelevel\"] - 1\n\n                            --Logger.log(level..\"已完成处理一个嵌套表！\")\n\n                            tbl[tempkey] = temptable\n\n                            count_key = count_key - 1\n\n                            tempfield = \"\"\n\n                            sontableamount = sontableamount - 1\n\n\n\n                            --Logger.log(level..\"（表）tempfield清零\")\n\n                            onmorestrtyping = false\n\n                        else\n\n                            tempfield = tempfield .. tostring(v)\n\n                            sontableamount = sontableamount - 1\n\n                            --Logger.log(level..\"已录入完一个子表\")\n\n\n\n\n                        end\n                    end\n\n\n\n                    if tostring(v) ~= \"{\" and tostring(v) ~= \"}\" then\n\n\n\n\n\n\n\n                        --Logger.log(level..\"（表）tempfield被写为\"..tempfield)\n\n                        tempfield = tempfield .. tostring(v)\n\n                        --Logger.log(level..\"tempfield被写为\"..tempfield)\n\n\n                    end\n\n\n\n\n                end\n\n\n            end\n\n            --Logger.log(level..\"已返回最终结果。\")\n\n            return tbl\n\n\n\n        end,\n\n\n\n        complete = function(tb, targettb, temp) ---@targettb为模板表，按照targettb将tb中不包含的键一一赋值\n            if temp == nil then\n                model = targettb\n            else\n                model = temp\n            end\n\n\n            for i, v in pairs(model) do\n\n                if type(v) ~= \"table\" and type(tb[i]) == nil then\n\n                    tb[i] = model[i]\n                end\n\n                if type(v) == \"table\" and type(tb[i]) == \"nil\" then\n\n                    tb[i] = model[i]\n                end\n\n\n\n                if type(v) == \"table\" and type(tb[i]) == \"table\" then\n\n                    tb[i] = Octopus.logic.complete(tb[i], targettb, v)\n                end\n\n\n\n            end\n\n            return tb\n\n        end,\n\n        length = function(table)\n\n            local count = 0\n            for i, v in pairs(table) do\n                count = count + 1\n            end\n            return count\n\n\n        end,\n        ---@return table\n        sortkeybynumber = function(table)\n            local c = 0\n            local temp = {}\n            for i, v in pairs(table) do\n                c = c + 1\n                temp[tostring(c)] = v\n            end\n            return temp\n        end,\n        ---@param table table\n        ---@return table add obj in the end\n        append = function(table, obj)\n            table = Octopus.logic.sortkeybynumber(table)\n            table[tostring(Octopus.logic.length(table) + 1)] = obj\n            return table\n\n        end\n\n    },\n    LOG = {\n        writelog = function(text)\n            if GLOBAL_LOG == nil then\n                GLOBAL_LOG = \"\"\n            end\n\n            GLOBAL_LOG = GLOBAL_LOG .. text .. \"\\n\"\n        end,\n        showlog = function()\n            Octopus.GUI.Menu.open(GLOBAL_LOG)\n        end,\n        clearlog = function()\n            GLOBAL_LOG = \"\"\n\n        end,\n        error = function(text)\n            effect(\"text\", args, 'error:' .. text, \"4\")\n            effect(\"text\", args, 'error:' .. text, \"1\")\n        end\n    },\n\n    Assests = {\n        PICTURES = {\n            HEADLINE = \"{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:312:64}\"\n        },\n        SoundLibrary = {\n\n            UI = {\n\n\n                CANCEL = 44310,\n                JIHESHI = 47615,\n                DIG = 193991,\n                MACHINE = 138317,\n                GEAR = 138318,\n                MAGIC = 12988,\n                FLAME = 145118,\n                CLICK = 169567,\n                ATTACK = 177165,\n                SUCCESS = 165970,\n                DICE = 36629\n\n            }\n\n        },\n\n        Icons = {\n\n            ['mage'] = '{icon:classicon_mage:16}',\n            ['warrior'] = '{icon:classicon_warrior:16}',\n            ['warlock'] = '{icon:classicon_warlock:16}',\n            ['deathknight'] = '{icon:classicon_deathknight:16}',\n            ['demonhunter'] = '{icon:classicon_demonhunter:16}',\n            ['hunter'] = '{icon:classicon_hunter:16}',\n            ['monk'] = '{icon:classicon_monk:16}',\n            ['paladin'] = '{icon:classicon_paladin:16}',\n            ['priest'] = '{icon:classicon_priest:16}',\n            ['rogue'] = '{icon:classicon_rogue:16}',\n            ['shaman'] = '{icon:classicon_shaman:16}',\n            ['druid'] = '{icon:classicon_druid:16}',\n            ['others'] = '{icon:ability_xaril_masterpoisoner_red:16}',\n            ['evoker'] = '{icon:classicon_evoker:16}'\n\n        },\n        Colour = {\n            paint = function(text, colour)\n\n                text = \"{col:\" .. colour .. \"}\" .. text .. \"{/col}\"\n\n                return text\n\n            end,\n\n            GREY = \"878787\",\n            RED = \"FF0500\",\n            DARK_RED = \"680200\",\n            LIGHT_GREEN = \"44FF56\",\n            DARK_BLUE = \"020082\",\n\n\n        }\n\n\n    },\n\n\n    GUI = {\n        PixelMonitor = {\n            --{x1 = {y1}}\n            new = function(size) ---@param size table {length,width}\n                local length = size[1]\n                local width = size[2]\n                --could not be nil\n                length = length or 32\n                width = width or 32\n                local monitor = {}\n                local a = 0\n                local b = 0\n\n                local function drawapixel()\n                    return {\n                        colour = \"FFFFFF\",\n                        link = \"NOLINK\",\n                    }\n                end\n\n                while a < length do\n                    a = a + 1\n                    monitor[tostring(a)] = {}\n                    while b < width do\n                        b = b + 1\n                        monitor[tostring(a)][tostring(b)] = drawapixel()\n\n                    end\n                    b = 0\n                end\n                return monitor\n\n\n            end,\n            setter = function(monitor, mode, Aargs) --mode : point[{x,y,value}],line[{x1,y1,x2,y2,value}],square[{x1,y1,x2,y2,value}],(NOTFINISHED)circle[{x,y,value}],(NOTFINISHED)fill[{x,y,tolerance,value}]\n                local function set(x, y, value)\n                    monitor[tostring(x)][tostring(y)][\"colour\"] = value\n                    Octopus.LOG.writelog(string.format(\"[Octopus.GUI.PixelMonitor]Setted colour in location (%s,%s) with %s\"\n                        , tostring(x), tostring(y), value))\n                end\n\n                local function coordinate_is_legal(monitor, coordinate) ---@param coordinate table {x,y}\n                    coordinate[1] = coordinate[1] or -999\n                    coordinate[2] = coordinate[2] or -999\n                    local gety = function(m)\n                        local a = 0\n                        for i, v in pairs(m[\"1\"]) do\n                            a = a + 1\n\n                        end\n                        return a\n\n                    end\n                    local x = Octopus.logic.length(monitor)\n                    local y = gety(monitor)\n                    if (coordinate[1] < x) and (coordinate[2] < y) then\n                        return true\n                    else\n                        return false\n                    end\n                end\n\n                --one point mode\n                if mode == \"point\" then\n                    local x = Aargs[1]\n                    local y = Aargs[2]\n                    local value = Aargs[3]\n                    if coordinate_is_legal(monitor, { x, y }) then\n                        set(x, y, value)\n                    else\n                        return nil\n                    end\n                end\n\n\n                if mode == \"line\" then\n                    local function isStrict(x1, y1, x2, y2)\n                        if x1 == x2 or y1 == y2 then\n                            return true\n                        else\n                            return false\n                        end\n                    end\n\n                    local function getDirect(x1, y1, x2, y2)\n                        if x1 == x2 then\n                            return \"x\"\n                        end\n                        if y1 == y2 then\n                            return \"y\"\n                        end\n                    end\n\n                    local x1 = Aargs[1]\n                    local y1 = Aargs[2]\n                    local x2 = Aargs[3]\n                    local y2 = Aargs[4]\n                    x1, x2 = math.min(x1, x2), math.max(x1, x2)\n                    y1, y2 = math.min(y1, y2), math.max(y1, y2)\n                    local value = Aargs[5]\n                    if coordinate_is_legal(monitor, { x1, y1 }) and coordinate_is_legal(monitor, { x2, y2 }) then\n                        if isStrict(x1, y1, x2, y2) then\n                            local Direct = getDirect(x1, y1, x2, y2)\n                            if Direct == \"x\" then\n                                while y1 <= y2 do\n                                    set(x1, y1, value)\n                                    y1 = y1 + 1\n                                end\n                            elseif Direct == \"y\" then\n                                while x1 <= x2 do\n                                    set(x1, y1, value)\n                                    x1 = x1 + 1\n                                end\n                            end\n                        else\n                            local xl = math.abs(x2 - x1)\n                            local yl = math.abs(y2 - y1)\n                            local big = math.max(xl, yl)\n                            local small = math.min(xl, yl)\n\n                            local function getamountmap(x1, y1, x2, y2) --to make a map that introduce the way pixel spread\n                                local basic = math.floor(big / small)\n                                local sp = basic + 1\n                                local fd = 0\n                                local sp_time = big % small\n                                local i = 0\n                                local map = {}\n\n                                while i < big do\n                                    i = i + 1\n                                    map[i] = basic\n                                end\n\n                                if sp_time > 0 then\n                                    local j = 0\n                                    local k = 1\n                                    local case = 0\n                                    while j < sp_time do\n                                        if case == 0 then\n                                            map[j] = sp\n                                            case = 1\n                                        else\n                                            map[-j] = sp\n                                            case = 0\n                                            k = k + 1\n                                        end\n                                    end\n                                end\n                                return map\n\n                            end\n\n                            local map = getamountmap(x1, y1, x2, y2)\n                            for i, drawtime in pairs(map) do\n                                local q = 0\n                                while q < drawtime do\n                                    set(x1, y1, value)\n                                    if xl == big then\n                                        y1 = y1 + 1\n                                    else\n                                        x1 = x1 + 1\n\n                                    end\n                                    if xl == big then\n                                        x1 = x1 + 1\n                                    else\n                                        y1 = y1 + 1\n                                    end\n                                    set(x1, y1, value)\n\n                                end\n                            end\n\n                        end\n                    end\n                end\n                if mode == \"square\" then\n                    local x1 = Aargs[1]\n                    local y1 = Aargs[2]\n                    local x2 = Aargs[3]\n                    local y2 = Aargs[4]\n                    local value = Aargs[5]\n                    local max_x = math.max(x1, x2)\n                    local max_y = math.max(x1, x2)\n                    local min_x = math.min(x1, x2)\n                    local min_y = math.min(y1, y2)\n                    local flag_x = min_x\n                    local flag_y = min_y\n                    if coordinate_is_legal(monitor, { x1, y1 }) and coordinate_is_legal(monitor, { x2, y2 }) then\n                        while flag_x <= max_x do\n                            while flag_y <= max_y do\n                                set(flag_x, flag_y)\n                                flag_y = flag_y + 1\n                            end\n                            flag_x = flag_x + 1\n                        end\n                    end\n                end\n\n\n            end,\n            BuildText = function(monitor, label)\n                local text = \"{h3:c}\"\n                for i, v in pairs(monitor) do\n                    for j, k in pairs(v) do\n                        text = text .. string.format(\"{col:%s}%s{/col}\", k['colour'], label)\n                    end\n                    text = text .. \"\\n\"\n                end\n                text = text .. '{/h3}'\n                return text\n\n            end\n\n\n        },\n        Menu = {\n\n\n            set = function(text)\n\n                setVar(args, \"c\", \"MenuText\", text)\n\n            end,\n            show = function(...)\n                --Menu.close()\n                Octopus.GUI.Menu.Config.MenuItem_UseAble(\"FALSE\")\n                effect(\"run_workflow\", args, \"c\", \"open_menu\")\n            end,\n\n            show_without_close = function()\n                effect(\"run_workflow\", args, \"c\", \"open_menu\")\n            end,\n\n            open_without_close = function(text)\n\n                setVar(args, \"c\", \"MenuText\", text)\n                Octopus.Data.save(\"OctopusOptions\", \"MENU_RECORD_LATEST\", \"FALSE\")\n                effect(\"run_workflow\", args, \"c\", \"open_menu\")\n\n            end,\n\n            open = function(text)\n\n                --Menu.close()\n                setVar(args, \"c\", \"MenuText\", text)\n                Octopus.GUI.Menu.Config.MenuItem_UseAble(\"FALSE\")\n                Octopus.Data.save(\"OctopusOptions\", \"MENU_RECORD_LATEST\", \"TRUE\")\n                effect(\"run_workflow\", args, \"c\", \"open_menu\")\n\n            end,\n            disable_record = function()\n                Octopus.Data.save(\"OctopusOptions\", \"MENU_RECORD_LATEST\", \"FALSE\")\n            end,\n\n            setlatest = function(text)\n\n                setVar(args, \"c\", \"LatestMenu\", text)\n\n            end,\n\n            openlatest = function()\n\n                Octopus.GUI.Menu.open(getVar(args, \"c\", \"LatestMenu\"))\n\n            end,\n\n            close = function()\n                if Octopus.Data.get_value(\"OctopusOptions\", \"MENU_RECORD_LATEST\") == \"TRUE\" then\n                    Octopus.GUI.Menu.setlatest(getVar(args, \"c\", \"MenuText\"))\n                end\n                Octopus.GUI.Menu.Config.MenuItem_UseAble(\"TRUE\")\n\n\n                effect(\"run_workflow\", args, \"c\", \"close_menu\")\n            end,\n\n            linkinfotemplate = {\n\n                scriptname = {\n                    [\"1\"] = 'DefaultLinkScript',\n                    [\"2\"] = 'DefaultLinkScript',\n                    [\"3\"] = 'DefaultLinkScript',\n                    [\"4\"] = 'DefaultLinkScript',\n                    [\"5\"] = 'DefaultLinkScript',\n                    [\"6\"] = 'DefaultLinkScript',\n                },\n\n                scriptargs = {\n                    [\"1\"] = 'noargs',\n                    [\"2\"] = 'noargs',\n                    [\"3\"] = 'noargs',\n                    [\"4\"] = 'noargs',\n                    [\"5\"] = 'noargs',\n                    [\"6\"] = 'noargs',\n                }\n\n\n\n\n\n            },\n\n            LinkSetter = function(linkinfo) --传入一个表，{\"scriptname\" = {[\"1\"] = ...},\"scriptargs\" = {...}}\n\n                linkinfo = Octopus.logic.complete(linkinfo, Octopus.GUI.Menu.linkinfotemplate)\n                for i, v in pairs(linkinfo[\"scriptname\"]) do\n                    setVar(args, \"c\", \"MenuScript_\" .. i, v)\n                end\n                for i, v in pairs(linkinfo[\"scriptargs\"]) do\n                    setVar(args, \"c\", \"MenuArgs_\" .. i, v)\n                end\n\n            end,\n            -- setVar(args,\"c\",\"ScriptArgs\",getVar(args,\"c\",\"MenuArgs_input\"..getVar(args,\"c\",\"link_input_case\")))\n\n            LinkSetter_input = function(linkinfo) --传入一个表，{\"scriptname\" = {[\"1\"] = ...},\"scriptargs\" = {...}}\n\n                linkinfo = Octopus.logic.complete(linkinfo, Octopus.GUI.Menu.linkinfotemplate)\n                for i, v in pairs(linkinfo[\"scriptname\"]) do\n\n                    setVar(args, \"c\", \"MenuScript_input\" .. i, v)\n                end\n                for i, v in pairs(linkinfo[\"scriptargs\"]) do\n\n                    setVar(args, \"c\", \"MenuArgs_input\" .. i, v)\n                end\n\n            end,\n\n            Config = {\n                ---@param text \"Menu_CloseAble\" || \"MenuItem_UseAble\"\n                ---@param value \"TRUE\" || \"FALSE\"\n                set = function(text, value)\n                    setVar(args, \"c\", text, value)\n                end,\n\n                CloseAble = function(text)\n\n                    if text == nil then\n                        return getVar(args, \"c\", \"Menu_CloseAble\")\n                    else\n                        Octopus.GUI.Menu.Config.set(\"Menu_CloseAble\", text)\n                    end\n                end,\n\n\n                MenuItem_UseAble = function(text)\n                    if text == nil then\n                        return getVar(args, \"c\", \"MenuItem_UseAble\")\n                    else\n                        Octopus.GUI.Menu.Config.set(\"MenuItem_UseAble\", text)\n                    end\n                end,\n\n                Confirming = function(text)\n                    if text == nil then\n                        return getVar(args, \"c\", \"Menu_Confirming\")\n                    else\n                        Octopus.GUI.Menu.Config.set(\"Menu_Confirming\", text)\n                    end\n                end,\n\n            },\n\n            --用来快速构造一些有功能的菜单\n            Builder = {\n\n\n                confirmation = function(confirmtype, descripe, warns, scriptname, ...) --确认窗口\n                    --[[\n                    会弹出一个确认菜单：\n                    你确定要： confirmtype 吗？\n                    descripe\n                    warns\n                    并锁定菜单使其无法被关闭\n        \n                ]]   --\n\n                    local menutext = \"{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:312:64}\\n\"\n                    if type(confirmtype) ~= nil then\n                        menutext = menutext .. \"{h1:c}你确定要：{col:670001} \" .. confirmtype .. \" {/col}吗？{/h1}\\n\"\n                    end\n                    if type(descripe) ~= nil then\n                        menutext = menutext .. \"{h2:c}\" .. descripe .. \"{/h2}\\n\"\n                    end\n                    if type(warns) ~= nil then\n                        menutext = menutext .. \"{h3:c}{col:ff2800}\" .. warns .. \"{/col}{/h3}\\n\"\n                    end\n                    menutext = menutext ..\n                        \"{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:312:64}{h1:c}{link*confirm*{icon:inv_misc_ticket_tarot_twistingnether_01:16}}{col:71ff50}{link*confirm*确定}\"\n                        ..\n                        \"\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\\t\" ..\n                        \"{/col}{col:BA2026}{link*cancel*取消}{/col}{link*cancel*{icon:70_inscription_deck_immortality:16}}{/h1}\"\n                    menutext = menutext .. \"\\n\"\n                    setVar(args, \"c\", \"ScriptName\", scriptname)\n                    Octopus.GUI.Menu.Config.Confirming(\"TRUE\")\n\n                    return menutext\n\n\n\n                end,\n\n                choose = function(objects, lore, afterrun) --objtemplate = {[\"1\"] = {text = \"\",scriptname = \"\",scriptargs = \"\",},}\n                    local title = \"{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:312:64}{h1:c}请选择：\" ..\n                        lore .. \"{/h1}{h2:c}\\n\"\n                    local text = title\n\n                    local o = \"\"\n                    local c = 0\n                    local pc = 0\n                    local p = 1\n                    local lc = 0\n                    local pages = {}\n                    pages[\"1\"] = {\n                        linksetter = {\n                            scriptname = {},\n                            scriptargs = {}\n                        }\n                    }\n\n                    while c < Octopus.logic.length(objects) do\n\n                        c = c + 1\n                        o = objects[tostring(c)] ---@class objtemplate\n                        if pc < 5 then\n                            pc = pc + 1\n                            text = text .. o[\"text\"] .. \"{link*\" .. \"link\" .. tostring(pc) .. \"*选择}\\n\"\n                            lc = lc + 1\n                            pages[tostring(p)][\"linksetter\"][\"scriptname\"][tostring(lc)] = \"choose_selecetedvalue\"\n                            pages[tostring(p)][\"linksetter\"][\"scriptargs\"][tostring(lc)] = o[\"scriptargs\"]\n\n\n\n\n                        end\n                        if pc == 5 or c + 1 > Octopus.logic.length(objects) then\n\n                            pc = 0\n                            lc = 0\n                            text = text .. \"\\n{link*choose.last*上一页} 第 \" ..\n                                tostring(p) .. \" 页 {link*choose.next*下一页}\\n\\n\"\n                            text = text ..\n                                Octopus.Assests.Colour.paint(\"{link*choose.cancel*取消选择}\\n\",\n                                    Octopus.Assests.Colour.DARK_RED)\n                            text = text .. \"{/h2}{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:312:64}\"\n\n                            pages[tostring(p)][\"text\"] = text\n                            text = title\n                            p = p + 1\n                            pages[tostring(p)] = {\n                                linksetter = {\n                                    scriptname = {},\n                                    scriptargs = {}\n                                }\n                            }\n                        end\n                        setVar(args, \"c\", \"temp_choose_pages\", Octopus.logic.tostring(pages))\n                        Octopus.GUI.Menu.open(pages[\"1\"][\"text\"])\n                        Octopus.GUI.Menu.LinkSetter(pages[\"1\"][\"linksetter\"])\n                        setVar(args, \"c\", \"choose_afterrun\", afterrun)\n                        setVar(args, \"c\", \"choose_nowopenpage\", \"1\")\n\n\n                    end\n\n\n                end,\n                ---@param objects table\n                ---@param lore string\n                ---@param afterrun string the name of the script that will execute after cancel\n                ---@param maxinpage integer max objects in per page\n                choose2 = function(objects, lore, afterrun, maxinpage) --objtemplate = {[\"1\"] = {text = \"\",scriptname = \"\",scriptargs = \"\",},}\n                    local title = \"{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:312:64}{h1:c}请选择：\" ..\n                        lore .. \"{/h1}{h2:c}\\n\"\n                    local text = title\n\n                    local o = \"\"\n                    local c = 0\n                    local pc = 0\n                    local p = 1\n                    local pages = {}\n                    maxinpage = maxinpage or 5\n                    pages[\"1\"] = {}\n\n                    while c < Octopus.logic.length(objects) do\n                        c = c + 1\n                        o = objects[tostring(c)] ---@class objtemplate\n                        if pc < maxinpage then\n                            pc = pc + 1\n                            text = text .. o[\"text\"] .. \"{link*\" .. \"runner(scriptname=\" .. o[\"scriptname\"]\n                                .. \",scriptargs=\" .. o[\"scriptargs\"] .. \")\"\n                                .. \"*选择}\\n\"\n                        end\n                        if pc == maxinpage or c + 1 > Octopus.logic.length(objects) then\n\n                            pc = 0\n                            text = text ..\n                                \"\\n{link*runner(scriptname=choose_page,scriptargs=last)*上一页} 第 \" ..\n                                tostring(p) .. \" 页 {link*runner(scriptname=choose_page,scriptargs=next)*下一页}\\n\\n\"\n                            text = text ..\n                                Octopus.Assests.Colour.paint(\"{link*runner(scriptname=choose_cancel)*取消选择}\\n\",\n                                    Octopus.Assests.Colour.DARK_RED)\n                            text = text .. \"{/h2}{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:312:64}\"\n\n                            pages[tostring(p)][\"text\"] = text\n                            --nextpage\n                            text = title\n                            p = p + 1\n                            pages[tostring(p)] = {}\n                        end\n                        Octopus.Data.save(\"temp_choose_pages\", nil, pages)\n                        Octopus.GUI.Menu.open(pages[\"1\"][\"text\"])\n                        setVar(args, \"c\", \"choose_nowopenpage\", \"1\")\n                        setVar(args, \"c\", \"choose_afterrun\", afterrun)\n\n\n                    end\n\n\n                end\n\n\n\n\n\n\n            },\n            choose_getvalue = function()\n                local a = getVar(args, \"c\", \"temp_choose_result\")\n\n                setVar(args, \"c\", \"temp_choose_result\", \"cancel\")\n\n                return a\n\n            end,\n\n\n        },\n    }\n    ,\n    Data = {\n        ---详见Octopus(Data Logic).png\n        ---保存一个值到指定目录\n\n        ---@param folder string\n        ---@param name string||nil\n        ---@param value any\n        save = function(folder, name, value)\n            --.foldername 储存一个表\n            --使用get_value直接获取表中的一个值\n            --如果name为nil，直接覆盖目录为value\n            local folderlist = Octopus.logic.strtotable(getVar(args, \"c\", \".*folderlist\"))\n\n            local function hasregisteredfolder(foldername)\n                local folderlist = Octopus.logic.strtotable(getVar(args, \"c\", \".*folderlist\")) --带*号的是不开放式目录\n                if folderlist ~= nil then\n                    for i, v in pairs(folderlist) do\n                        if v == foldername then\n                            return true\n                        end\n                    end\n                end\n                return false\n            end\n\n            local function init()\n                setVar(args, \"c\", \".*folderlist\", \"{}\")\n            end\n\n            local function registerfolder(foldername)\n                --{[1]=xxx}\n                folderlist[#folderlist + 1] = foldername\n                setVar(args, \"c\", \".*folderlist\", Octopus.logic.tostring(folderlist))\n                setVar(args, \"c\", \".\" .. foldername, \"{}\")\n\n            end\n\n            if tostring(getVar(args, \"c\", \".*folderlist\")) == \"nil\" then\n                init()\n            end\n\n            --如果是value表就把它变成可储存字段\n            if type(value) ~= \"string\" then\n                if type(value) == 'number' then\n                    value = tostring(value)\n                elseif type(value) == 'function' then --函数是取返回值\n                    value = value()\n                end\n            end\n\n\n            if tostring(name) ~= 'nil' then\n                local fd = Octopus.logic.strtotable(getVar(args, \"c\", \".\" .. folder))\n                ---@diagnostic disable-next-line: need-check-nil\n                fd[name] = value\n                setVar(args, \"c\", \".\" .. folder, Octopus.logic.tostring(fd))\n            else\n                setVar(args, \"c\", \".\" .. folder, Octopus.logic.tostring(value))\n            end\n\n            if hasregisteredfolder(folder) then\n                registerfolder(folder)\n            end\n\n\n\n\n\n        end,\n        ---@param folder string\n        ---@param name string\n        get_value = function(folder, name)\n            return Octopus.logic.strtotable(getVar(args, \"c\", \".\" .. folder))[name]\n        end,\n        ---@param folder string\n        get_folder = function(folder)\n\n            return Octopus.logic.strtotable(getVar(args, \"c\", \".\" .. folder))\n\n\n        end,\n        cleartemp = function()\n            for i, folder_name in pairs(Octopus.Data.get_folder(\"*folderlist\")) do\n                if string.find(folder_name, \"temp_\") ~= nil then\n                    Octopus.Data.save(folder_name, nil, nil)\n                end\n            end\n        end,\n        ---@param scriptname string\n        ---@param value any\n        ---@\n        send = function(scriptname, value)\n\n            if type(value) == \"number\" then\n                value = tostring(value)\n            elseif type(value) == \"table\" then\n                value = Octopus.logic.tostring(value)\n            end\n\n\n            effect(\"signal_send\", args, scriptname, value)\n        end,\n        eventargs_analysis = function()\n            local EventArgs = getVar(args, \"c\", \"EventArgs\")\n            local tmp = {}\n            local c = 0\n            while string.find(EventArgs, \"||\") ~= nil do\n                c = c + 1\n                local t = string.sub(EventArgs, 1, string.find(EventArgs, \"||\") - 1)\n                tmp[tostring(c)] = t\n                EventArgs = EventArgs:sub(EventArgs:find(\"||\") + 1, #EventArgs)\n\n            end\n            return tmp\n        end,\n    },\n    Sound = {\n\n        playSoundSelf = function(soundID)\n\n            effect(\"sound_id_self\", args, nil, soundID)\n\n        end\n\n    },\n    Listener = {\n        ---@diagnostic disable-next-line: undefined-doc-name\n        open = function(Aargs) ---@param Aargs listner listner:{type = ,scriptname = scriptname,id = id}\n            local type = Aargs[\"type\"]\n            local id = Aargs[\"id\"]\n            setVar(args, \"c\", type, \"TRUE\")\n            local R_Listner = Octopus.Data.get_folder(\"RegisteredListener\")\n            if R_Listner[type] ~= nil then\n                R_Listner[type][id] = { scriptname = Aargs[\"scriptname\"] }\n            else\n                R_Listner[type] = {}\n                R_Listner[type][id] = { scriptname = Aargs[\"scriptname\"] }\n            end\n            Octopus.Data.save(\"RegisteredListener\", nil, R_Listner)\n        end,\n        ---@diagnostic disable-next-line: undefined-doc-name\n        ---@param type string\n        ---@param id string\n        close = function(type, id)\n\n            local listners = Octopus.Listener.get()\n            if listners[type] ~= nil then\n                listners[type][id] = nil\n            end\n            if Octopus.logic.length(listners[type]) == 0 then\n                setVar(args, \"c\", type, \"FALSE\")\n            end\n            Octopus.Data.save(\"RegisteredListener\", nil, listners)\n        end,\n\n        ---@param type string the type of the listner (OnMessage_system/OnMessage_say/OnMessage_yell/OnMessage_emote/OnMessage_raid/OnMessage_party/OnPlayerStartMove/Always/OnTRP3_roll/OnTRP3_kill/OnTRP3_item_used)\n        ---@param scriptname string the script that the listner will execute\n        ---@param id string the id of the lisner,must be unique\n        new = function(type, scriptname, id)\n            id = id or \"DEFAULT\"\n            if type == \"OnMessage_say\" or\n                type == \"OnMessage_yell\" or\n                type == \"OnMessage_emote\" or\n                type == \"OnMessage_raid\" or\n                type == \"OnMessage_party\" or\n                type == \"OnPlayerStartMove\" or\n                type == \"Always\" or\n                type == \"OnTRP3_roll\" or\n                type == \"OnTRP3_kill\" or\n                type == \"OnTRP3_item_used\" or\n                type == \"OnMessage_system\"\n            then\n                return { type = type, scriptname = scriptname, id = id }\n            else\n                error(\"ERROR:Invaild Listener Type\")\n            end\n        end,\n        ---@return table listners\n        get = function()\n            return Octopus.Data.get_folder(\"RegisteredListener\")\n        end,\n        save = function(table)\n            Octopus.Data.save(\"RegisteredListener\", nil, table)\n        end\n\n\n\n    },\n\n    RunScript = function(scriptname, scripts) --运行指定脚本\n\n        for i, v in pairs(scripts) do\n\n            if type(v) == \"table\" then\n                Octopus.RunScript(scriptname, v)\n\n            else\n                if i == scriptname then\n                    scripts[scriptname]()\n                end\n            end\n\n        end\n\n    end,\n    BasicScripts = {\n        menuclose = function()\n\n            if Octopus.GUI.Menu.Config.Confirming() == \"TRUE\" then\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n\n                effect(\"text\", args, \"已取消！\", \"4\")\n\n                Octopus.GUI.Menu.Config.Confirming(\"FALSE\")\n\n                --                Octopus.GUI.Menu.openlatest()\n            end\n\n\n\n            if Octopus.GUI.Menu.Config.CloseAble() ~= \"FALSE\" then\n\n\n                Octopus.GUI.Menu.setlatest(getVar(args, \"c\", \"MenuText\"))\n\n                Octopus.GUI.Menu.Config.MenuItem_UseAble(\"TRUE\")\n\n\n            else\n\n                Octopus.GUI.Menu.show()\n\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n\n                effect(\"text\", args, \"此页面不能被关闭！\", \"4\")\n\n            end\n        end,\n        ListnerRelatives = {\n            ListenerHeard = function()\n                local listners = Octopus.Data.get_folder(\"RegisteredListener\")\n                local atype = ScriptArgs\n\n                for i, v in pairs(listners[atype]) do\n                    ScriptArgs = v[\"scriptargs\"]\n                    Octopus.RunScript(v[\"scriptname\"], SCRIPTS)\n                end\n            end\n        },\n\n\n        windup = function()\n            setVar(args, \"c\", \"ScriptName\", \"nil\")\n            setVar(args, \"c\", \"ScriptArgs\", \"nil\")\n            setVar(args, \"c\", \"ScriptFilter\", \"nil\")\n        end\n\n    }\n\n\n}\n\n---章鱼END\nRunScript = Octopus.RunScript\n\n\nSignal = {\n\n    send = function(tag, text)\n\n        effect(\"signal_send\", args, tag, text)\n\n    end,\n\n    analysis = function()\n\n\n        SignalValue = getVar(args, \"c\", \"SIGNAL_TEXT\")\n        local tag = getVar(args, \"c\", \"SIGNAL_TAG\")\n\n        RunScript(tag, SCRIPTS)\n\n    end\n\n}\n\n\nMenuLibrary = {\n    FIRSTTIME_LOADING = {\n    },\n\n    MAIN = \"{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:256:64}\" ..\n        \"\\n{h2:c}>>>冒险大师<<<\\nAdventureMaster\\n{col:2a2a2a}KP界面{/col}{/h2}\\n\" ..\n        \"{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:256:64}\\n\" ..\n        \"{h1:c}{link*playerlist.open*{icon:ability_paladin_beaconsoflight:16}}\" ..\n        \"{link*playerlist.open*玩家管理}{link*playerlist.open*{icon:ability_paladin_beaconsoflight:16}}\" ..\n        \"\\n\\n{link*statecontrol*{icon:petbattle_health:16}}{link*statecontrol*状态控制}{link*statecontrol*{icon:petbattle_health:16}}\\n\\n\"\n        ..\n        \"{link*dicemanage*{icon:inv_misc_dice_02:16}}{link*runner(scriptname=diceroller_openmenu)*判定界面}\" ..\n        \"{link*statecontrol*{icon:inv_misc_dice_02:16}}\\n\\n\" ..\n        \"{link*minigames*{icon:inv_prg_icon_puzzle14:16}}{link*runner(scriptname=author_word)*意见反馈}\" ..\n        \"{link*minigames*{icon:inv_prg_icon_puzzle14:16}}\\n{/h1}\"\n    ,\n    DiceRoller_Main = Octopus.Assests.PICTURES.HEADLINE ..\n        \"{h1:c}骰子判定{/h1}\\n\\n\\n\" ..\n        \"{h3:c}{link*runner(scriptname=diceroller_judge_menu)*{icon:ability_warrior_commandingshout:42}}{/h3}\" ..\n        \"{h2:c}{link*runner(scriptname=diceroller_judge_menu)*发起判定}{/h2}\" .. \"\\n\\n\\n\\n\\n\" ..\n        \"{h3:c}{link*runner(scriptname=diceroller_dicestream_menu)*{icon:inv_relics_hourglass:42}}{/h3}\" ..\n        \"{h2:c}{link*runner(scriptname=diceroller_dicestream_menu)*管理判定流}{/h2}\"\n        .. Octopus.Assests.PICTURES.HEADLINE\n        .. \"{h2:c}{link*runner(scriptname=tomain)*返回主界面}{/h2}\"\n    ,\n    DiceRoller_Dicestream_Main = function()\n        local text = Octopus.Assests.PICTURES.HEADLINE .. \"{h3:c}\"\n        local pages = {}\n        local dicestreams = Octopus.Data.get_folder(\"DiceStreamLibrary\")\n\n        --打印已有的骰子流\n        if Octopus.logic.length(dicestreams) > 0 then\n            local c = 0\n            for i, v in pairs(dicestreams) do\n\n                c = c + 1\n                local ds = dicestreams[tostring(c)]\n                text = text ..\n                    string.format(\"%s: %s(需要:%s,奖励%s,%sd%s) %s\\n\",\n                        tostring(c),\n                        ds[\"judge_type\"],\n                        ds[\"needed_point\"],\n                        ds[\"award_point\"],\n                        ds[\"dice_num\"],\n                        ds[\"dice_surface\"],\n                        string.format(\"{link*runner(scriptname=%s,scriptargs=%s)*更改}\",\n                            \"dicestream_set\",\n                            tostring(c)\n                        )\n                    )\n            end\n        else\n            text = text .. \"还没有判定流！\\n\"\n        end\n        text = text .. \"{link*runner(scriptname=dicestream_new)*+新建判定流+}\"\n        text = text .. \"{/h3}\" .. Octopus.Assests.PICTURES.HEADLINE\n            .. \"{h2:c}{link*runner(scriptname=diceroller_openmenu)*返回上一级}{/h2}\"\n        return text\n    end,\n    Diceroller_sender_main = function()\n\n        local target = Utils.PlayerList.getTargetInfo()\n        local player_name = \"\"\n        local player_class = \"\"\n        if target ~= 'notaplayer' then\n            player_name = target['name']\n            player_class = Octopus.Assests.Icons[target[\"class\"]]\n        else\n            player_class = \"\"\n            player_name = \"没有玩家\"\n        end\n        local text = Octopus.Assests.PICTURES.HEADLINE\n        local dicestream = {}\n        local sender_info = Octopus.Data.get_folder(\"Diceroller_sender_info\")\n        if Octopus.logic.length(sender_info) < 1 then\n            sender_info = {\n                dicestream_id = \"1\",\n                judge_mode = \"solo\", --team\n                sender_mode = \"online\", --offline\n                team_mode = \"allpass\" --sum\n            }\n            Octopus.Data.save(\"Diceroller_sender_info\", nil, sender_info)\n        end\n        dicestream = Octopus.Data.get_folder(\"DiceStreamLibrary\")[sender_info[\"dicestream_id\"]]\n\n        text = text .. \"{h1:c}判定准备{/h1}\"\n            .. \"{h3:c}你当前的目标：\" .. player_class .. player_name\n            ..\n            \"\\n选择的判定流：\" ..\n            sender_info[\"dicestream_id\"] .. \"{link*runner(scriptname=dicesender_change,scriptargs=dicestream_id)*选择}\"\n            .. string.format(\"\\n{col:e0e0e0}(%s,需要%s,奖励%s,%sd%s){/col}\\n\",\n                dicestream[\"judge_type\"],\n                dicestream[\"needed_point\"],\n                dicestream[\"award_point\"],\n                dicestream[\"dice_num\"],\n                dicestream[\"dice_surface\"])\n            .. \"判定模式（单人(1)/群体(2)）：\" .. LangTrans.SENDER_OPTION[sender_info[\"judge_mode\"]]\n            .. \"　{link*runner(scriptname=dicesender_change,scriptargs=judge_mode)*切换}\\n\"\n            .. \"{col:525252}单人：对一个玩家发送掷骰/群体：所有【已在玩家列表】的玩家都可掷骰（/roll）并统计{/col}\\n\"\n        if sender_info[\"judge_mode\"] == \"team\" then\n            text = text .. \"　　群体模式 全过(1)/总和(2)：\" ..\n                LangTrans[\"SENDER_OPTION\"][sender_info[\"team_mode\"]]\n                .. \"　{link*runner(scriptname=dicesender_change,scriptargs=team_mode)*切换}\"\n\n            text = text .. \"\\n{col:525252}全过：所有玩家都要通过（暂时只支持单骰判定）/总和：所有玩家总和超过即可{/col}\\n\"\n        end\n        if sender_info['judge_mode'] == 'solo' then\n            text = text .. \"发送模式（在线(1)/离线(2)）：\" ..\n                LangTrans.SENDER_OPTION[sender_info[\"sender_mode\"]]\n                .. \"　{link*runner(scriptname=dicesender_change,scriptargs=sender_mode)*切换}\\n\"\n                .. \"{col:525252}在线：双方必须互为目标，并且都开启了《冒险大师》剧本(对群体模式无效)/离线：对方无需打开《冒险大师》剧本，使用/roll进行roll点{/col}\"\n        end\n        text = text .. \"{/h3}\\n\\n\"\n            .. \"{h2:c}{link*runner(scriptname=diceroller_sender_send)*发送！}{/h2}\"\n\n\n\n        text = text .. Octopus.Assests.PICTURES.HEADLINE\n        text = text .. \"{h2:c}{link*runner(scriptname=diceroller_openmenu)*返回上一级}{/h2}\"\n        return text\n    end,\n    --单人等待中\n    Diceroller_sender_waiting1 = function()\n        local text = Octopus.Assests.PICTURES.HEADLINE\n        text = text .. (\"{h1:c}等待\" .. getVar(args, \"c\", \"sender_targetplayer\") .. \"的反馈\\n......{/h1}\")\n            .. \"\\n\\n{h3:c}{link*runner(scriptname=diceroller_judge_cancel)*点击取消}{/h3}\"\n            .. Octopus.Assests.PICTURES.HEADLINE\n        return text\n\n    end,\n    --群体等待中\n    Diceroller_sender_waiting2 = function()\n        --[[\n            temp_results = {[1] = {...}}\n            --]]\n        local text = Octopus.Assests.PICTURES.HEADLINE\n        local tmps = Octopus.Data.get_folder(\"temp_results\") --results\n        local sender_info = Octopus.Data.get_folder(\"Diceroller_sender_info\")\n        text = text .. (\"{h1:c}得到的反馈信息（%s）{/h1}\"):format(LangTrans.SENDER_OPTION[\n            sender_info['team_mode']])\n            .. (\"{h3:c}{col:606060}(共 %s 条){/col}{/h3}\"):format(\n                tostring(Octopus.logic.length(tmps))\n            )\n\n        if sender_info['team_mode'] == \"allpass\" then\n            text = text .. \"{h2:c}\"\n            local i = 0\n            while i < Octopus.logic.length(tmps) do\n                i = i + 1\n                local result = tmps[tostring(i)]\n                text = text\n                    .. (\"%s：玩家：%s||点数：%s||最终点数：%s||判定结果：%s\\n\"):format(\n                        tostring(i),\n                        result['1'],\n                        result['2'],\n                        result['4'],\n                        LangTrans.JUDGE_RESULT[result['5']]\n\n                    )\n\n            end\n\n        elseif sender_info['team_mode'] == \"sum\" then\n            local sumpoint = 0\n            local i = 0\n            while i < Octopus.logic.length(tmps) do\n                i = i + 1\n                local result = tmps[tostring(i)]\n                sumpoint = sumpoint + tonumber(result[\"4\"])\n\n            end\n\n            text = text .. \"{h2:c}\"\n            text = text .. (\"{col:0c98dc}>总计点数：%s<{/col}\\n\\n\"):format(\n                tostring(sumpoint)\n            )\n            local i = 0\n            while i < Octopus.logic.length(tmps) do\n                i = i + 1\n                local result = tmps[tostring(i)]\n                text = text\n                    .. (\"%s：玩家：%s||点数：%s||最终点数：%s\\n\"):format(\n                        tostring(i),\n                        result['1'],\n                        result['2'],\n                        result['4']\n                    )\n            end\n        end\n        text = text .. \"{/h2}\"\n            .. \"{h3:c}{link*runner(scriptname=dice_feedback_team_end)*结束并统计}{/h3}\"\n\n        text = text .. Octopus.Assests.PICTURES.HEADLINE\n        return text\n\n    end,\n    ---@param Aargs table {[1]:countplayer,[2]:sumresult,[3]:winner,[4]failure,[5]:drawer,[6]:sumpoint,[7]sorted_result}\n    DiceRoller_sender_team_end = function(Aargs)\n        Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.FLAME)\n\n        local sender_info = Octopus.Data.get_folder(\"Diceroller_sender_info\")\n        local dicestream = Octopus.Data.get_folder(\"DiceStreamLibrary\")[sender_info['dicestream_id']]\n\n        local text = Octopus.Assests.PICTURES.HEADLINE\n            .. \"{h1:c}群体判定结果{/h1}\"\n            .. (\"{h3:c}共收到反馈 %s 份{/h3}\"):format(tostring(Aargs[1]))\n\n        if sender_info['team_mode'] == 'allpass' then\n            text = text .. (\"{h2:c}{col:23d50f}>通过判定的玩家<{/col}{/h2}\")\n                .. \"{h3:c}\"\n            for i, v in pairs(Aargs[3]) do\n                text = text .. v .. \"\\n\"\n            end\n            text = text .. \"{/h3}\"\n            text = text .. (\"{h2:c}{col:ca0000}>未通过判定的玩家<{/col}{/h2}\")\n                .. \"{h3:c}\"\n            for i, v in pairs(Aargs[4]) do\n                text = text .. v .. \"\\n\"\n            end\n            text = text .. \"{/h3}\"\n            text = text .. (\"{h2:c}{col:187e94}>判定平局的玩家<{/col}{/h2}\")\n                .. \"{h3:c}\"\n            for i, v in pairs(Aargs[5]) do\n                text = text .. v .. \"\\n\"\n            end\n            text = text .. \"{/h3}\"\n        elseif sender_info['team_mode'] == 'sum' then\n            text = text .. (\"{h2:c}{col:23d50f}>总计点数<{/col}{/h2}\")\n                .. (\"{h1:c}%s{/h1}\"):format(tostring(Aargs[6]))\n                .. (\"{h2:c}{col:23d50f}>结果<{/col}{/h2}\")\n                .. (\"{h1:c}%s{/h1}\"):format(LangTrans.JUDGE_RESULT[tostring(Aargs[2])])\n        end\n        text = text .. (\"{h2:c}>点数排行<{/h2}{h3:c}\")\n        local i = 0\n        while i < Octopus.logic.length(Aargs[7]) do\n            i = i + 1\n            local v = Aargs[7][tostring(i)]\n            text = text .. (\"%s：%s（%s(+%s)）\\n\"):format(\n                tostring(i),\n                v['1'],\n                tostring(v['2']),\n                dicestream['award_point']\n            )\n        end\n        text = text .. \"{/h3}\"\n\n\n        text = text .. Octopus.Assests.PICTURES.HEADLINE\n\n        text = text .. \"{h2:c}{link*runner(scriptname=diceroller_judge_menu)*返回上一级}{/h2}\"\n        text = text .. \"{h2:c}{link*runner(scriptname=tomain)*返回主界面}{/h2}\"\n        return text\n    end,\n    Diceroller_judgeGUI = function()\n        local judge_info = Octopus.Data.get_folder(\"Judging_Info\")\n        if Octopus.logic.length(judge_info) > 0 then\n            local text = Octopus.Assests.PICTURES.HEADLINE\n            text = text .. \"{h1:c}！你正在进行判定！{/h1}{h2:c}\"\n                .. (\"来自：%s\\n\"):format(judge_info[\"sender\"])\n                .. (\"判定内容：%s\\n\"):format(judge_info[\"judge_type\"])\n                .. (\"需要点数：%s\\n\"):format(judge_info[\"needed_point\"])\n                .. (\"额外奖励点：%s\\n\"):format(judge_info[\"award_point\"])\n                .. (\"骰子面数：%s\\n\"):format(judge_info[\"dice_surface\"])\n                .. (\"骰子数量：%s\\n\"):format(judge_info[\"dice_num\"])\n                .. \"{/h2}\\n\"\n                .. (\"{h3:c}{icon:inv_misc_dice_01:25}{link*%s*>>点击掷出骰子<<}{icon:inv_misc_dice_01:25}\"):format(\n                    \"runner(scriptname=diceroller_roll)\")\n                .. (\"\\n{col:df0000}{link*runner(scriptname=diceroller_roll_cancel)*点击取消}{/col}{/h3}\")\n                .. Octopus.Assests.PICTURES.HEADLINE\n            return text\n        else\n            Octopus.LOG.error(\"没有正在进行的判定。\")\n        end\n    end,\n    Diceroller_judgeGUI_final = function(judge_result, identy)\n        local text = Octopus.Assests.PICTURES.HEADLINE\n        Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.FLAME)\n        identy = identy or \"sender\"\n        text = text .. \"{h1:c}判定完成{/h1}\"\n            .. \"{h2:c}\"\n            .. (\"得到的点数：%s\\n\"):format(judge_result[\"point\"])\n            .. (\"加成后点数：%s\\n\"):format(judge_result[\"total_point\"])\n            .. (\"判定结果：%s\"):format(LangTrans.JUDGE_RESULT[judge_result['result']])\n            .. \"{/h2}\"\n\n\n            .. Octopus.Assests.PICTURES.HEADLINE\n        if identy == \"receiver\" then\n            text = text .. \"{h2:c}{link*runner(scriptname=tomain)*返回主界面}{/h2}\"\n        else\n\n            text = text .. \"{h2:c}{link*runner(scriptname=diceroller_judge_menu)*返回上一级}{/h2}\"\n            text = text .. \"{h2:c}{link*runner(scriptname=tomain)*返回主界面}{/h2}\"\n        end\n        return text\n    end,\n    Helper = function()\n        local pic_endofstorm = \"{icon:inv_stormswake:128}\"\n        local text           = Octopus.Assests.PICTURES.HEADLINE\n            .. \"{h3:c}\"\n            .. pic_endofstorm .. \"{/h3}\"\n            .. \"{h2:c}意见反馈邮箱{/h2}\"\n            .. \"{h2:c}1120370331@qq.com\\n\\n{/h2}\"\n            .. \"\\n{h3:c}{col:4c4c4c}作者的牢骚\"\n            .. \"\\n虽然这个小剧本的功能目前还挺邵少的，但是在开发这个物品的过程中，\"\n            .. \"我同时写了很多的开发框架，所以实际开发时间还挺长的……已经有三千多行代码了(｀·ω·‘)\"\n            .. \"做这个的目的是为了让一些活动能更有特色吧。也是为了让KP在指挥扔骰子的时候不那么忙了。\"\n            .. \"随着国服的关服，这个物品又该何去何从呢~\"\n            .. \"其实我还有一些其他的想法，比如加一个可以内置在这里面的任务系统，让所有人都可以一键发布任务，但还是，过段时间再说吧~无论如何，请您享用这个小玩意ヽ(·ω·){/h3}\"\n            .. Octopus.Assests.PICTURES.HEADLINE\n            .. \"{h2:c}{link*runner(scriptname=tomain)*返回主界面}{/h2}\"\n        return text\n    end\n\n\n\n}\n\n\nLangTrans = {\n\n    STATES = {\n        extended = {\n            health = \"{icon:petbattle_health:16}{col:ae0000}生命{/col}{icon:petbattle_health:16}\",\n            coins = \"{icon:inv_misc_coin_02:16}{col:f4e200}金币{/col}{icon:inv_misc_coin_02:16}\",\n            foucs = \"{icon:petbattle_speed:16}{col:008080}精力{/col}{icon:petbattle_speed:16}\",\n            sanity = \"{icon:spell_nzinsanity_dontlook:16}{col:5f00bd}理智{/col}{icon:spell_nzinsanity_dontlook:16}\",\n            rp_points = \"{icon:inv_holiday_beerfest_highmountain:16}{col:ffffff}参与点数{/col}{icon:inv_holiday_beerfest_highmountain:16}\"\n        },\n        health = \"生命\",\n        coins = \"金币\",\n        focus = \"精力\",\n        sanity = \"理智\",\n        rp_points = \"参与点数\",\n    },\n    SENDER_OPTION = {\n        solo = \">>单人<<\",\n        team = \">>群体<<\",\n        offline = \">>离线<<\",\n        online = \">>在线<<\",\n        allpass = \">>全过<<\",\n        sum = \">>总和<<\"\n    },\n    JUDGE_RESULT = {\n        [\"DEFAULT\"] = {\n            TRUE = \"成功\",\n            FALSE = \"失败\",\n            DRAW = \"平局\"\n        },\n\n        FALSE = \"{icon:misc_rnrredxbutton:16}{col:aa0000}失败{/col}{icon:misc_rnrredxbutton:16}\",\n        DRAW = \"{icon:inv_progenitorjellyfishpet_light:16}平局{icon:inv_progenitorjellyfishpet_light:16}\",\n        TRUE = \"{icon:ability_deathwing_grasping_tendrilsgreen:16}{col:00b900}成功{/col}{icon:ability_deathwing_grasping_tendrilsgreen:16}\"\n    }\n\n}\n\n\nUtils = {\n\n\n    PlayerList = {\n\n\n        ---@return table player , string \"notaplayer\"\n        getTargetInfo = function()\n            if op(\"unit_is_player\", args, \"target\") == true then\n\n\n\n                local UNIT_NAME = op(\"unit_name\", args, \"target\")\n\n                local UNIT_CLASS = op(\"unit_class\", args, \"target\")\n\n                local UNIT_TYPE = op(\"unit_creature_type\", args, \"target\")\n\n                return { name = UNIT_NAME, class = UNIT_CLASS, type = UNIT_TYPE }\n            else\n                return \"notaplayer\"\n            end\n\n\n\n        end,\n\n        addPlayer = {\n\n            execute = function()\n                local info = Utils.PlayerList.getTargetInfo()\n\n                if tostring(op(\"unit_is_player\", args, \"target\")) == \"true\" then\n                    setVar(args, \"c\", \"temp_playerinfo\", Octopus.logic.tostring(info))\n                    Octopus.GUI.Menu.setlatest(getVar(args, \"c\", \"MenuText\"))\n                    Octopus.GUI.Menu.open(Octopus.GUI.Menu.Builder.confirmation(\"添加玩家到角色列表\",\n                        \"玩家名：\" .. info[\"name\"] .. \"\\n\" ..\n                        \"职业：\" .. Octopus.Assests.Icons[info[\"class\"]] .. \"\\n\"\n\n                        , \"请确认无误\",\n                        \"addPlayer_next\"))\n                    Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.MAGIC)\n\n                else\n                    Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n                    effect(\"text\", args, \"你必须选中一个玩家！\", \"4\")\n                end\n\n            end\n\n        },\n\n        PlayerLibrarySort = function()\n            local Pl = Utils.PlayerList.getList()\n            local Sorted = {}\n            local c = 0\n            for i, v in pairs(Pl) do\n                c = c + 1\n                Sorted[tostring(c)] = v\n            end\n            Utils.PlayerList.setList(Sorted)\n        end\n        ,\n\n\n\n        PlayerLibrary = {\n\n\n            --[[\n            \n\n            \n            ]] --\n\n        },\n\n        playertemplate = {\n\n            name = \"没有名字\",\n            class = \"others\",\n            type = \"others\",\n\n            state = {\n\n                health = 10,\n                coins = 10,\n                focus = 10,\n                sanity = 10,\n                rp_points = 0,\n                inventory = {\n\n                }\n\n            }\n\n\n\n        },\n\n        getList = function()\n            return Octopus.logic.strtotable(getVar(args, \"c\", \"PlayerList\"))\n\n        end,\n\n        setList = function(list)\n            setVar(args, \"c\", \"PlayerList\", Octopus.logic.tostring(list))\n\n        end,\n\n        savePlayer = function(playerinfo)\n\n            playerinfo = Octopus.logic.complete(playerinfo, Utils.PlayerList.playertemplate)\n\n            local t = Octopus.logic.strtotable(getVar(args, \"c\", \"PlayerList\"))\n            local has = false\n\n            for i, v in pairs(t) do\n                if Octopus.logic.conclude(v, playerinfo['name']) == true then\n                    has = true\n                end\n            end\n            if has == false then\n                t[Octopus.logic.length(t) + 1] = playerinfo\n                setVar(args, \"c\", \"PlayerList\", Octopus.logic.tostring(t))\n            else\n                effect('text', args, \"该玩家已经在列表中了！\", \"4\")\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n            end\n        end,\n\n        showListMenu = function()\n\n            local function ListMenuMaker()\n\n                local list = Utils.PlayerList.getList()\n                local title = \"{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:312:64}\\n{h1:c}>>玩家列表<<{/h1}\"\n                local counter = 0\n                local acounter = 0\n                local ct2 = 0\n                local pages = {}\n                local p_counter = 0\n                local text = title --设置头部文字\n                local sub = \"{col:868686}{h2:c}{link*tomain*返回主界面}{/h2}{/col}\"\n                local page_namelist = {}\n                local player = {}\n                pages[\"info\"] = {}\n\n                if Octopus.logic.tostring(list) ~= \"{}\" then\n\n                    text = text .. \"{h2:c}\"\n\n\n                    while acounter < Octopus.logic.length(list) do\n                        counter = counter + 1\n                        acounter = acounter + 1\n                        ct2 = ct2 + 1\n                        player = list[tostring(acounter)]\n                        if counter <= 5 then\n\n                            page_namelist[counter] = player[\"name\"]\n\n                            text = text .. string.format(\"%s: %s%s||体力：%s||%s\\n\",\n                                tostring(acounter),\n                                Octopus.Assests.Icons[player.class],\n                                player[\"name\"],\n                                tostring(player.state.health),\n                                string.format(\"{link*link%s*详细信息}\", tostring(counter)))\n\n                        end\n                        if counter == 5 or Octopus.logic.haskey(list, tostring(acounter + 1)) == false then\n                            p_counter = p_counter + 1\n\n                            text = text\n                            text = text ..\n                                \"{link*playerlist.lastpage*上一页}\" ..\n                                string.format(\"第 %s 页\", tostring(p_counter)) .. \"{link*playerlist.nextpage*下一页}\\n\"\n                            text = text .. \"\\n{link*playerlist.addplayer*添加玩家}{link*playerlist.delplayer*删除玩家}\"\n                            text = text .. \"{/h2}\"\n                            text = text .. sub\n\n\n                            pages[tostring(p_counter)] = {}\n                            pages[tostring(p_counter)][\"text\"] = text\n                            pages[tostring(p_counter)][\"namelist\"] = page_namelist\n                            page_namelist = {}\n                            text = title .. \"{h2:c}\"\n                            counter = 0\n                        end\n\n\n                    end\n\n\n                else\n                    text = text .. \"{h2:c}还没有添加玩家！{/h2}\"\n                    text = text .. \"{h3:c}{link*playerlist.addplayer*点击添加一个玩家}{/h3}\"\n                        .. Octopus.Assests.PICTURES.HEADLINE\n                    text = text .. sub\n                    pages[\"1\"] = {}\n                    pages[\"1\"][\"text\"] = text\n                    pages[\"1\"][\"namelist\"] = { [\"1\"] = \"noname\" }\n                end\n\n\n                pages[\"info\"][\"maxpage\"] = p_counter\n                pages[\"info\"][\"playernum\"] = ct2\n\n\n\n\n\n                return pages\n\n\n\n\n\n\n            end\n\n            local Pages = ListMenuMaker()\n\n            setVar(args, \"c\", \"PlayerListPages\", Octopus.logic.tostring(Pages))\n\n\n\n            Utils.PlayerList.openpage(\"first\")\n\n\n\n        end,\n\n        openpage = function(arg)\n\n            local function NoPageError()\n\n                effect(\"text\", args, \"没有更多的页数了！\", \"4\")\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n\n            end\n\n            local Pages = Octopus.logic.strtotable(getVar(args, \"c\", \"PlayerListPages\"))\n\n            local nowpage = tonumber(getVar(args, \"c\", \"PlayerListPages_openPage\"))\n\n            local function LinkLoader(pagenum)\n\n                local a = (pagenum - 1) * 5 + 1 --ID\n                local b = pagenum * 5 --Last ID\n                local c = 0 --Slot\n                local lf = { scriptname = {}, scriptargs = {} }\n                local PlayerList = Utils.PlayerList.getList()\n\n\n                while a <= b and a <= Octopus.logic.length(PlayerList) do\n                    c = c + 1\n                    lf[\"scriptname\"][tostring(c)] = \"playerlist_details\"\n                    lf[\"scriptargs\"][tostring(c)] = tostring(a)\n                    a = a + 1\n                end\n                Octopus.GUI.Menu.LinkSetter(lf)\n\n\n\n\n            end\n\n            if arg == \"first\" then\n                local pagenum = 1\n                Octopus.GUI.Menu.open(Pages[\"1\"][\"text\"])\n                local lf = { scriptname = {}, scriptargs = {} }\n                LinkLoader(pagenum)\n\n\n                setVar(args, \"c\", \"PlayerListPages_openPage\", \"1\")\n\n            elseif arg == \"next\" then\n                if Pages[\"info\"][\"maxpage\"] - nowpage > 0 then\n\n                    Octopus.GUI.Menu.open(Pages[tostring(nowpage + 1)][\"text\"])\n                    local lf = { scriptname = {}, scriptargs = {} }\n                    local c = 0\n                    LinkLoader(nowpage + 1)\n                    Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n\n\n                    setVar(args, \"c\", \"PlayerListPages_openPage\", nowpage + 1)\n                else\n                    NoPageError()\n\n                end\n            elseif arg == \"last\" then\n                if nowpage - 1 > 0 then\n                    Octopus.GUI.Menu.open(Pages[tostring(nowpage - 1)][\"text\"])\n                    local lf = { scriptname = {}, scriptargs = {} }\n                    local c = 0\n                    LinkLoader(nowpage - 1)\n                    Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n                    setVar(args, \"c\", \"PlayerListPages_openPage\", nowpage - 1)\n\n                else\n                    NoPageError()\n\n\n                end\n            end\n        end,\n\n        showPlayerDetails = function(id)\n\n\n            id = tostring(id)\n            local player = Utils.PlayerList.getList()[id]\n            setVar(args, \"c\", \"Selected_PlayerID\", id)\n\n\n            local function MenuBuilder(Player)\n\n                local title = string.format(\"{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:312:64}\\n{h1:c}%s 的个人信息{/h1}\"\n                    , Player[\"name\"])\n                local text = title\n                text = text .. \"{h2:c}\"\n                text = text .. string.format(\"{icon:petbattle_health:16}剩余体力：%s{icon:petbattle_health:16}%s\",\n                    Player[\"state\"][\"health\"],\n                    \"{col:717171}{link*link_input1*改变}{/col}\\n\")\n\n                text = text .. string.format(\"{icon:inv_eyeofnzothpet:16}剩余理智：%s{icon:inv_eyeofnzothpet:16}%s\"\n                    ,\n                    Player[\"state\"][\"sanity\"],\n                    \"{col:717171}{link*link_input2*改变}{/col}\\n\")\n\n                text = text .. string.format(\"{icon:inv_misc_coin_02:16}剩余金币：%s{icon:inv_misc_coin_02:16}%s\",\n                    Player[\"state\"][\"coins\"],\n                    \"{col:717171}{link*link_input3*改变}{/col}\\n\")\n\n                text = text ..\n                    string.format(\"{icon:ability_garrison_orangebird:16}剩余精力：%s{icon:ability_garrison_orangebird:16}%s\"\n                        ,\n                        Player[\"state\"][\"focus\"],\n                        \"{col:717171}{link*link_input4*改变}{/col}\\n\")\n\n                text = text ..\n                    string.format(\"{icon:achievement_faction_brewmaster:16}参与点数：%s{icon:achievement_faction_brewmaster:16}%s\"\n                        ,\n                        Player[\"state\"][\"rp_points\"],\n                        \"{col:717171}{link*link_input5*改变}{/col}\\n\")\n\n                text = text .. \"{/h2}\\n\\n\\n\\n{h3:c}{col:717171}{link*playerlist.open*返回上一级}{/col}{/h3}\"\n                text = text .. \"{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:312:64}\"\n\n                return text\n\n\n\n            end\n\n            Octopus.GUI.Menu.open(MenuBuilder(player))\n            Octopus.GUI.Menu.LinkSetter_input(\n                {\n                    scriptname = {\n\n                        \"playerdetails_change\",\n                        \"playerdetails_change\",\n                        \"playerdetails_change\",\n                        \"playerdetails_change\",\n                        \"playerdetails_change\",\n                        \"playerdetails_change\",\n\n                    },\n                    scriptargs = {\n                        \"health\",\n                        \"sanity\",\n                        \"coins\",\n                        \"focus\",\n                        \"rp_points\"\n\n                    }\n                }\n            )\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n        end,\n\n        findbyname = function(name)\n            local PL = Utils.PlayerList.getList()\n            for i, v in PL do\n                if v[\"name\"] == name then\n                    return v\n                end\n            end\n            return nil\n\n\n        end\n\n\n\n\n    },\n    StateControl = {\n\n        States = {\n\n\n            set = function(id, statetype, value)\n\n                local PL = Utils.PlayerList.getList()\n                id = tostring(id)\n                PL[id]['state'][statetype] = value\n                effect(\"text\", args, string.format(\"已为你设置 %s 的 %s 为 %s!\",\n                    PL[id]['name'],\n                    LangTrans.STATES[statetype],\n                    tostring(value)), \"3\")\n                Utils.PlayerList.setList(PL)\n                Utils.PlayerList.showPlayerDetails(id)\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.SUCCESS)\n            end,\n            set2 = function(id, statetype, value) --不打开个人详细信息的set\n                local PL = Utils.PlayerList.getList()\n                id = tostring(id)\n                PL[id]['state'][statetype] = value\n                Utils.PlayerList.setList(PL)\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.SUCCESS)\n            end,\n\n            operate = function(operation, id, type) --进行加操作，返回操作后的数值\n                local PL = Utils.PlayerList.getList()\n                id = tostring(id)\n                operation = tonumber(operation)\n                PL[id][\"state\"][type] = tonumber(PL[id][\"state\"][type]) + operation\n                Utils.PlayerList.setList(PL)\n                return PL[id][\"state\"][type]\n\n            end,\n\n        },\n        openMainMenu = function()\n\n            local MenuBuilder = function(Aargs) --valuetype是数据的类型，只有number或string\n\n\n                local text = \"\"\n                text = text .. \"{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:256:64}{h1:c}属性设置{/h1}\"\n\n                text = text ..\n                    \"{h2:c}选择的玩家：\" ..\n                    Aargs['playername'] ..\n                    Octopus.Assests.Colour.paint(\"{link*link1*选择}\", Octopus.Assests.Colour.DARK_BLUE) .. \"\\n\"\n\n                text = text ..\n                    \"改变项目：\" ..\n                    Aargs[\"type\"] ..\n                    Octopus.Assests.Colour.paint(\"{link*link2*选择}\", Octopus.Assests.Colour.DARK_BLUE) .. \"\\n\"\n\n                text = text .. \"当前值：\" .. Aargs[\"nowvalue\"] .. \"\\n\"\n\n                text = text .. \"---------------------------------------------\\n\"\n\n                if Aargs[\"valuetype\"] == \"number\" then\n\n                    text = text .. string.format(\n                        \"%s %s %s{/h2}\",\n                        \"{link*link_input1*增加}\",\n                        \"{link*link_input2*减少}\",\n                        \"{link*link_input3*设定}\"\n                    )\n                elseif Aargs[\"valuetype\"] == \"notype\" then\n                    text = text .. \"{/h2}{h1:c}请先选择一个玩家！{/h1}\"\n                else\n                    text = text .. Octopus.Assests.Colour.paint(\"数据类型错误\", Octopus.Assests.Colour.RED)\n                end\n\n                text = text .. \"{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:256:64}\\n\"\n                text = text .. Octopus.Assests.Colour.paint(\"{h2:c}{link*tomain*返回主界面}{/h2}\",\n                    Octopus.Assests.Colour.GREY)\n\n                return text\n\n\n            end\n\n\n\n\n            if tostring(getVar(args, \"c\", \"StateControl_Selected_id\")) == \"nil\" or\n                tonumber(getVar(args, \"c\", \"StateControl_Selected_id\")) >\n                Octopus.logic.length(Utils.PlayerList.getList()) then --第一次初始化\n\n                Octopus.GUI.Menu.open(MenuBuilder({\n                    playername = \"未选择\",\n                    type = LangTrans.STATES.health,\n                    nowvalue = \"0\",\n                    valuetype = \"notype\"\n                }))\n                setVar(args, \"c\", \"StateControl_openMainMenu\", \"FALSE\")\n                setVar(args, \"c\", \"StateControl_Selected_type\", \"health\")\n\n            else\n                local Player = Utils.PlayerList.getList()[getVar(args, \"c\", \"StateControl_Selected_id\")]\n                local type = getVar(args, \"c\", \"StateControl_Selected_type\")\n                local nowvalue = Player[\"state\"][type]\n                local name = Player[\"name\"]\n                Octopus.GUI.Menu.open(\n                    MenuBuilder({\n                        playername = name,\n                        type = LangTrans.STATES[type],\n                        nowvalue = nowvalue,\n                        valuetype = \"number\"\n                    }))\n            end\n\n            Octopus.GUI.Menu.LinkSetter(\n                {\n                    scriptname = {\n                        [\"1\"] = \"state_open_chooseplayer\",\n                        [\"2\"] = \"state_open_choosetype\",\n                    },\n                    scriptargs = {\n\n                    }\n                })\n\n            Octopus.GUI.Menu.LinkSetter_input(\n                {\n                    scriptname = {\n                        [\"1\"] = \"states_add\",\n                        [\"2\"] = \"states_minus\",\n                        [\"3\"] = \"states_set\",\n                    },\n                    scriptargs = {}\n\n                }\n            )\n\n\n\n\n        end\n\n    },\n    DiceRoller = {\n\n        DiceStreamLibrary = {\n\n            [\"1\"] = {\n\n                dice_num = 1,\n                dice_surface = 100,\n                judge_type = \"开锁\",\n                needed_point = \"50\",\n                award_point = \"0\",\n            }\n\n        },\n\n        DiceStream = {\n            getLibrary = function()\n                return Octopus.Data.get_folder(\"DiceStreamLibrary\")\n            end,\n            saveLibrary = function(table)\n                Octopus.Data.save(\"DiceStreamLibrary\", nil, table)\n            end,\n            openMaker = function()\n\n                local function MenuBuilder(Aargs)\n\n                    local title = \"{img:Interface\\\\QUESTFRAME\\\\UI-HorizontalBreak:256:64}\\n{h1:c}判定流制作器{/h1}\"\n                    local text = title\n                    text = text .. \"{h2:c}\"\n                    text = text ..\n                        \"骰子数目：\" ..\n                        Aargs[\"dice_num\"] ..\n                        Octopus.Assests.Colour.paint(\"{link*link_input1*改变}\", Octopus.Assests.Colour.DARK_BLUE)\n                    text = text ..\n                        \"骰子最大值：\" ..\n                        Aargs[\"dice_surface\"] ..\n                        Octopus.Assests.Colour.paint(\"{link*link_input2*改变}\", Octopus.Assests.Colour.DARK_BLUE)\n                    text = text ..\n                        \"判定类型：\" ..\n                        Aargs[\"judge_type\"] ..\n                        Octopus.Assests.Colour.paint(\"{link*link_input3*改变}\", Octopus.Assests.Colour.DARK_BLUE)\n                    text = text ..\n                        \"判定所需点数：\" ..\n                        Aargs[\"judge_needed_point\"] ..\n                        Octopus.Assests.Colour.paint(\"{link*link_input4*改变}\", Octopus.Assests.Colour.DARK_BLUE)\n                    text = text ..\n                        \"奖励点数：\" ..\n                        Aargs[\"award_point\"] ..\n                        Octopus.Assests.Colour.paint(\"{link*link_input5*改变}\", Octopus.Assests.Colour.DARK_BLUE)\n                    text = text ..\n                        \"{link*link1*添加到判定流库}\\n{\" ..\n                        Octopus.Assests.Colour.paint(\"link*link2*回到上一级}\", Octopus.Assests.Colour.GREY)\n\n\n                    Octopus.GUI.Menu.LinkSetter_input(\n                        {\n                            scriptname = {\n                                [\"1\"] = \"dicemaker_setdice_num\",\n                                [\"2\"] = \"dicemaker_setdice_surface\",\n                                [\"3\"] = \"dicemaker_setjudge_type\",\n                                [\"4\"] = \"dicemaker_setjudge_needed_point\",\n                                [\"5\"] = \"dicemaker_setaward_point\",\n                            }\n                        }\n                    )\n\n                    Octopus.GUI.Menu.LinkSetter(\n                        {\n                            scriptname = {\n                                [\"1\"] = \"dicemaker_save\",\n                                [\"2\"] = \"dicemaker\"\n                            }\n                        }\n\n                    )\n\n\n\n\n                    return text\n\n                end\n\n                if tostring(getVar(args, \"c\", \"dicemaker_first\")) ~= \"nil\" or\n                    tostring(getVar(args, \"c\", \"dicemaker_first\")) == \"TRUE\" then\n                    Octopus.GUI.Menu.open(MenuBuilder(\n                        {\n                            dice_num = getVar(args, \"c\", \"dicemaker_dice_num\"),\n                            dice_surface = getVar(args, \"c\", \"dicemaker_dice_surface\"),\n                            judge_needed_point = getVar(args, \"c\", \"dicemaker_judge_needed_point\"),\n                            judge_type = getVar(args, \"c\", \"dicemaker_judge_type\"),\n                            award_point = getVar(args, \"c\", \"dicemaker_award_point\")\n\n                        }\n                    ))\n\n                else\n                    setVar(args, \"c\", \"dicemaker_first\", \"FALSE\")\n                    setVar(args, \"c\", \"dicemaker_dice_num\", \"1\")\n                    setVar(args, \"c\", \"dicemaker_dice_surface\", \"100\")\n                    setVar(args, \"c\", \"dicemaker_judge_type\", \"开锁\")\n                    setVar(args, \"c\", \"dicemaker_judge_needed_point\", \"50\")\n                    setVar(args, \"c\", \"dicemaker_award_point\", \"0\")\n                    Octopus.GUI.Menu.open(MenuBuilder(\n                        {\n                            dice_num = getVar(args, \"c\", \"dicemaker_dice_num\"),\n                            dice_surface = getVar(args, \"c\", \"dicemaker_dice_surface\"),\n                            judge_needed_point = getVar(args, \"c\", \"dicemaker_judge_needed_point\"),\n                            judge_type = getVar(args, \"c\", \"dicemaker_judge_type\"),\n                            award_point = getVar(args, \"c\", \"dicemaker_award_point\")\n\n                        }\n                    ))\n\n\n\n                end\n\n            end,\n            showtext = function(dicestream)\n                local text = \"\"\n                for i, v in pairs(dicestream) do\n                end\n            end,\n\n            openDicelist = function(case)\n                local obj = {}\n                local DL = Utils.DiceRoller.DiceStream.getLibrary()\n                for i, v in pairs(DL) do\n                    obj[i][\"text\"] = v[\"\"]\n\n                end\n                if case == \"select\" then\n\n\n                    Octopus.GUI.Menu.Builder.choose(\n                        {\n\n                        }\n                    )\n\n                end\n            end,\n\n\n            maker_save = function()\n                local dice_num = getVar(args, \"c\", \"dicemaker_dice_num\")\n                local dice_surface = getVar(args, \"c\", \"dicemaker_dice_surface\")\n                local judge_needed_point = getVar(args, \"c\", \"dicemaker_judge_needed_point\")\n                local judge_type = getVar(args, \"c\", \"dicemaker_judge_type\")\n                local award_point = getVar(args, \"c\", \"dicemaker_award_point\")\n                local dicestream = {\n                    dice_num = dice_num,\n                    dice_surface = dice_surface,\n                    judge_needed_point = judge_needed_point,\n                    judge_type = judge_type,\n                    award_point = award_point,\n                }\n                local DL = Utils.DiceRoller.DiceStream.getLibrary()\n                DL[tostring(#DL + 1)] = dicestream\n                effect(\"text\", args, \"已创建一条新的拼点流！\")\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.SUCCESS)\n\n\n\n            end,\n\n            template = {\n\n                dice_num = 1,\n                dice_surface = 100,\n                judge_type = \"开锁\",\n                needed_point = \"50\",\n                award_point = \"0\",\n            }\n        },\n        DiceSender = {\n            getted = function()\n\n            end,\n            display = function()\n\n            end,\n            ---@return table [1] = playername || [2]=dicepoint || [3]=dicesurface\n            systemmessage_process = function(text)\n                local playername = text:sub(1, text:find(\"掷\") - 1)\n                local dicepoint = text:sub(text:find(\"出\") + 3, text:find(\"（\") - 1)\n                local dicesurface = text:sub(text:find(\"（\") + 3, text:find(\"）\") - 1)\n                dicesurface = dicesurface:sub(dicesurface:find(\"-\") + 1, #dicesurface)\n                return { playername, dicepoint, dicesurface }\n            end,\n        },\n\n    },\n}\n\nEvents = {}\n\n\n\n\n\n\n\n\n\nSCRIPTS = {\n    getArgs = function()\n\n        return getVar(args, \"c\", \"ScriptArgs\")\n\n    end,\n\n    FunctionContinues = {\n\n        addPlayer_next = function()\n\n\n            local info = Octopus.logic.strtotable(getVar(args, \"c\", \"temp_playerinfo\"))\n\n\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.SUCCESS)\n            effect(\"text\", args, string.format(\"已添加 %s 至角色名单！\", info[\"name\"]), \"3\")\n\n            Utils.PlayerList.savePlayer(info)\n            Octopus.GUI.Menu.Config.Confirming(\"FALSE\")\n            Utils.PlayerList.showListMenu()\n\n        end,\n\n        state_choosed_player = function()\n            local value = Octopus.GUI.Menu.choose_getvalue()\n            if value ~= \"cancel\" then\n                setVar(args, \"c\", \"StateControl_Selected_id\", value)\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.SUCCESS)\n            end\n            Utils.StateControl.openMainMenu()\n\n\n        end,\n        state_choosed_type = function()\n            local value = Octopus.GUI.Menu.choose_getvalue()\n            if value ~= \"cancel\" then\n                setVar(args, \"c\", \"StateControl_Selected_type\", value)\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.SUCCESS)\n            end\n\n            Utils.StateControl.openMainMenu()\n        end,\n\n\n\n    },\n\n    MenuEffects = {\n        open_latest_menu_bycancel = function()\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n            effect(\"text\", args, \"已取消！\", \"3\")\n\n            Octopus.GUI.Menu.openlatest()\n\n        end,\n\n        menuclose = function()\n\n            if Octopus.GUI.Menu.Config.Confirming() == \"TRUE\" then\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n\n                effect(\"text\", args, \"已取消！\", \"4\")\n\n                Octopus.GUI.Menu.Config.Confirming(\"FALSE\")\n\n                --                Octopus.GUI.Menu.openlatest()\n            end\n\n\n\n            if Octopus.GUI.Menu.Config.CloseAble() ~= \"FALSE\" then\n\n\n                Octopus.GUI.Menu.setlatest(getVar(args, \"c\", \"MenuText\"))\n\n                Octopus.GUI.Menu.Config.MenuItem_UseAble(\"TRUE\")\n\n\n            else\n\n                Octopus.GUI.Menu.show()\n\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n\n                effect(\"text\", args, \"此页面不能被关闭！\", \"4\")\n\n            end\n        end\n    },\n\n    MenuLinks = {\n\n        playerlist = function()\n\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n\n            Utils.PlayerList.showListMenu()\n\n        end,\n        playerlist_details = function()\n            local Aargs = SCRIPTS.getArgs()\n\n            Utils.PlayerList.showPlayerDetails(Aargs)\n\n        end,\n\n        playerlist_nextpage = function()\n\n            Utils.PlayerList.openpage(\"next\")\n\n\n        end,\n        playerlist_lastpage = function()\n            Utils.PlayerList.openpage(\"last\")\n        end,\n        playerlist_addplayer = function()\n\n            Utils.PlayerList.addPlayer.execute()\n\n        end,\n        tomain = function()\n            Octopus.GUI.Menu.open(MenuLibrary.MAIN)\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n        end,\n\n        tolast = function()\n            Octopus.GUI.Menu.openlatest()\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n\n        end,\n\n        playerlist_delplayer = function()\n\n            local PlayerID = tostring(getVar(args, \"c\", \"Selected_PlayerName\"))\n\n            if PlayerID ~= \"nil\" and PlayerID ~= \"cancel\" then\n\n                local PL = Utils.PlayerList.getList()\n                local name = PL[PlayerID]['name']\n\n                if Octopus.logic.haskey(PL, PlayerID) then\n                    PL[PlayerID] = nil\n                    Utils.PlayerList.setList(PL)\n                    setVar(args, \"c\", \"Selected_PlayerName\", \"cancel\")\n                    effect(\"text\", args, \"已为你删除\" .. name .. \"的数据！\", \"3\")\n                    Utils.PlayerList.PlayerLibrarySort()\n                    Utils.PlayerList.showListMenu()\n                    Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.FLAME)\n                else\n                    effect(\"text\", args, \"没有此玩家的信息，请检查拼写！\", \"4\")\n                    Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n                end\n\n            else\n                effect(\"text\", args, \"已取消操作。\", \"4\")\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n            end\n        end,\n\n        playerdetails_change = function()\n            local type = SCRIPTS.getArgs()\n            local value = getVar(args, \"c\", \"temp_input\")\n            local PlayerID = tostring(getVar(args, \"c\", \"Selected_PlayerID\"))\n            Utils.StateControl.States.set(PlayerID, type, value)\n        end,\n        choose_lastpage = function()\n            local nowpage = tonumber(getVar(args, \"c\", \"choose_nowopenpage\"))\n            local pages = Octopus.logic.strtotable(getVar(args, \"c\", \"temp_choose_pages\"))\n            if nowpage - 1 > 0 then\n                Octopus.GUI.Menu.open(pages[tostring(nowpage - 1)][\"text\"])\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n                Octopus.GUI.Menu.LinkSetter(pages[tostring(nowpage - 1)][\"linksetter\"])\n                setVar(args, \"c\", \"choose_nowopenpage\", tostring(nowpage - 1))\n            else\n                effect(\"text\", args, \"没有更多的页数了。\", \"4\")\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n            end\n\n\n        end,\n        choose_nextpage = function()\n            local nowpage = tonumber(getVar(args, \"c\", \"choose_nowopenpage\"))\n            local pages = Octopus.logic.strtotable(getVar(args, \"c\", \"temp_choose_pages\"))\n            if nowpage + 1 < Octopus.logic.length(pages) then\n                Octopus.GUI.Menu.open(pages[tostring(nowpage + 1)][\"text\"])\n                Octopus.GUI.Menu.LinkSetter(pages[tostring(nowpage + 1)][\"linksetter\"])\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n                setVar(args, \"c\", \"choose_nowopenpage\", tostring(nowpage + 1))\n            else\n                effect(\"text\", args, \"没有更多的页数了。\", \"4\")\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n            end\n\n\n\n        end,\n        choose_page = function()\n            local nowpage = tonumber(getVar(args, \"c\", \"choose_nowopenpage\"))\n            local pages = Octopus.Data.get_folder(\"temp_choose_pages\")\n            if ScriptArgs == \"next\" then\n                if nowpage + 1 < Octopus.logic.length(pages) then\n                    Octopus.GUI.Menu.open(pages[tostring(nowpage + 1)][\"text\"])\n                    Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n                    setVar(args, \"c\", \"choose_nowopenpage\", tostring(nowpage + 1))\n                else\n                    effect(\"text\", args, \"没有更多的页数了。\", \"4\")\n                    Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n                end\n            elseif ScriptArgs == \"last\" then\n                if nowpage - 1 > 0 then\n                    Octopus.GUI.Menu.open(pages[tostring(nowpage - 1)][\"text\"])\n                    Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n                    setVar(args, \"c\", \"choose_nowopenpage\", tostring(nowpage - 1))\n                else\n                    effect(\"text\", args, \"没有更多的页数了。\", \"4\")\n                    Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n                end\n            end\n        end,\n\n\n\n        choose_cancel = function()\n            setVar(args, \"c\", \"temp_choose_result\", \"cancel\")\n            effect(\"text\", args, \"已取消。\", \"4\")\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n            Octopus.RunScript(getVar(args, \"c\", \"choose_afterrun\"), SCRIPTS)\n\n        end,\n\n        choose_selecetedvalue = function()\n            setVar(args, \"c\", \"temp_choose_result\", SCRIPTS.getArgs())\n            Octopus.RunScript(getVar(args, \"c\", \"choose_afterrun\"), SCRIPTS)\n\n        end,\n        choose_valueadd = function()\n\n        end,\n\n        state_open_chooseplayer = function()\n\n            local PL = Utils.PlayerList.getList()\n            local obj = {}\n            local c = 0\n            for i, v in pairs(PL) do\n                c = c + 1\n                obj[tostring(c)] = {}\n                obj[tostring(c)][\"text\"] = Octopus.Assests.Icons[v[\"class\"]] .. v[\"name\"]\n                obj[tostring(c)][\"scriptname\"] = \"state_choose_player\"\n                obj[tostring(c)][\"scriptargs\"] = i\n\n            end\n            Octopus.GUI.Menu.Builder.choose(obj, \"玩家\", \"state_choosed_player\")\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n\n        end,\n        state_open_choosetype = function()\n\n            local obj = {}\n            local c   = 0\n            for i, v in pairs(LangTrans.STATES.extended) do\n                c = c + 1\n                obj[tostring(c)] = {}\n                obj[tostring(c)][\"text\"] = v\n                obj[tostring(c)][\"scriptname\"] = \"state_choose_type\"\n                obj[tostring(c)][\"scriptargs\"] = i\n            end\n            Octopus.GUI.Menu.Builder.choose(obj, \"属性\", \"state_choosed_type\")\n\n        end,\n        open_statecontrol = function()\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n            Utils.StateControl.openMainMenu()\n\n        end,\n        states_add = function()\n            local operate = tonumber(getVar(args, \"c\", \"temp_input\"))\n            local PlayerID = getVar(args, \"c\", \"StateControl_Selected_id\")\n            local type = getVar(args, \"c\", \"StateControl_Selected_type\")\n            local PL = Utils.PlayerList.getList()\n            if tonumber(operate) ~= nil then\n                local feedback = Utils.StateControl.States.operate(operate, PlayerID, type)\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.SUCCESS)\n                effect(\"text\", args, string.format(\n                    \"【OOC】已为 %s 增加 %s 点 %s （剩余：%s）\",\n                    PL[PlayerID][\"name\"],\n                    tostring(operate),\n                    LangTrans.STATES[type],\n                    tostring(feedback)), \"3\")\n\n                effect(\"speech_player\", args, \"/e\", string.format(\"|| %s %s\",\n                    PL[PlayerID][\"name\"],\n                    string.format(\n                        \"【OOC】获得了 %s 点 %s （剩余：%s）\",\n                        tostring(operate),\n                        LangTrans.STATES[type],\n                        tostring(feedback)))\n\n\n                )\n                Utils.StateControl.openMainMenu()\n            else\n                effect(\"text\", args, \"非法的操作值！\", \"4\")\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n                Utils.StateControl.openMainMenu()\n            end\n        end,\n        states_minus = function()\n            local operate = tonumber(getVar(args, \"c\", \"temp_input\"))\n            local PlayerID = getVar(args, \"c\", \"StateControl_Selected_id\")\n            local type = getVar(args, \"c\", \"StateControl_Selected_type\")\n            local PL = Utils.PlayerList.getList()\n            if tonumber(operate) ~= nil then\n                local operate2 = operate - operate * 2\n                local feedback = Utils.StateControl.States.operate(operate2, PlayerID, type)\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.SUCCESS)\n                effect(\"text\", args, string.format(\n                    \"【OOC】已为 %s 扣除 %s 点 %s （剩余：%s）\",\n                    PL[PlayerID][\"name\"],\n                    tostring(operate),\n                    LangTrans.STATES[type],\n                    tostring(feedback)), \"3\")\n\n                effect(\"speech_player\", args, \"/e\", string.format(\"|| %s %s\",\n                    PL[PlayerID][\"name\"],\n                    string.format(\n                        \"【OOC】失去了 %s 点 %s （剩余：%s）\",\n                        tostring(operate),\n                        LangTrans.STATES[type],\n                        tostring(feedback)))\n\n\n                )\n                Utils.StateControl.openMainMenu()\n\n            else\n                effect(\"text\", args, \"非法的操作值！\", \"4\")\n                Utils.StateControl.openMainMenu()\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n            end\n        end,\n        states_set = function()\n\n            local operate = tonumber(getVar(args, \"c\", \"temp_input\"))\n            local PlayerID = getVar(args, \"c\", \"StateControl_Selected_id\")\n            local type = getVar(args, \"c\", \"StateControl_Selected_type\")\n            local PL = Utils.PlayerList.getList()\n            if tonumber(operate) ~= nil then\n                Utils.StateControl.States.set2(PlayerID, type, operate)\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.SUCCESS)\n                effect(\"text\", args, string.format(\n                    \"【OOC】已将 %s 的 %s 设置为 %s \",\n                    PL[PlayerID][\"name\"],\n                    LangTrans.STATES[type],\n                    tostring(operate)\n\n                ), \"3\")\n\n                effect(\"speech_player\", args, \"/e\", string.format(\"|| %s %s\",\n                    PL[PlayerID][\"name\"],\n                    string.format(\n                        \"【OOC】的 %s 被设置为 %s\",\n                        LangTrans.STATES[type],\n                        tostring(operate)\n\n\n                    )))\n                Utils.StateControl.openMainMenu()\n            else\n                effect(\"text\", args, \"非法的操作值！\", \"3\")\n                Utils.StateControl.openMainMenu()\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n            end\n\n        end,\n        diceroller_openmenu = function()\n            Octopus.GUI.Menu.open(MenuLibrary.DiceRoller_Main)\n        end,\n        diceroller_dicestream_menu = function()\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n            Octopus.GUI.Menu.open(MenuLibrary.DiceRoller_Dicestream_Main())\n        end,\n        dicestream_set = function()\n            local dicestream = Utils.DiceRoller.DiceStream.getLibrary()[ScriptArgs]\n            setVar(args, \"c\", \"dicestream_editingID\", ScriptArgs)\n            Octopus.Data.save(\"temp_editingdicestream\", nil, dicestream)\n            local text = Octopus.Assests.PICTURES.HEADLINE ..\n                \"{h1:c}判定流配置{/h1}{h3:c}\" ..\n                string.format(\n                    \"判定类型：%s %s\\n\",\n                    dicestream[\"judge_type\"],\n                    \"{link*input(scriptname=dicestream_setsave1,scriptargs=judge_type)*更改}\") ..\n                string.format(\n                    \"需要点数：%s %s\\n\",\n                    dicestream[\"needed_point\"],\n                    \"{link*input(scriptname=dicestream_setsave1,scriptargs=needed_point)*更改}\") ..\n                string.format(\n                    \"奖励点数：%s %s\\n\",\n                    dicestream[\"award_point\"],\n                    \"{link*input(scriptname=dicestream_setsave1,scriptargs=award_point)*更改}\") ..\n                string.format(\n                    \"骰子面数：%s %s\\n\",\n                    dicestream[\"dice_surface\"],\n                    \"{link*input(scriptname=dicestream_setsave1,scriptargs=dice_surface)*更改}\") ..\n                string.format(\n                    \"骰子数量：%s %s\\n\",\n                    dicestream[\"dice_num\"],\n                    \"{link*input(scriptname=dicestream_setsave1,scriptargs=dice_num)*更改}\") ..\n                \"\\n\" ..\n                \"{col:b30000}{link*runner(scriptname=dicestream_delete,scriptargs=\" ..\n                ScriptArgs .. \")*删除}{/col}{/h3}\" ..\n\n                Octopus.Assests.PICTURES.HEADLINE\n                .. \"{h2:c}{link*runner(scriptname=diceroller_dicestream_menu)*返回上一级}{/h2}\"\n            Octopus.GUI.Menu.open(text)\n\n        end,\n        dicestream_setsave1 = function()\n            local type = ScriptArgs\n            local value = getVar(args, \"c\", \"InputValue\")\n            local dicestream = Octopus.Data.get_folder(\"temp_editingdicestream\")\n            local function valid()\n                if type == \"needed_point\" or\n                    type == \"award_point\" or\n                    type == \"dice_num\" or\n                    type == \"dice_surface\"\n                then\n                    if (tonumber(value) ~= nil) and tonumber(value) % 1 == 0 then\n                        if type == \"dice_num\" or type == \"dice_surface\" then\n                            if tonumber(value) > 0 then\n                                return true\n                            end\n                        else\n                            return true\n                        end\n                    else\n                        return false\n                    end\n                else\n                    return true\n                end\n            end\n\n            if valid() == true then\n                dicestream[type] = value\n                Octopus.Data.save(\"DiceStreamLibrary\",\n                    getVar(args, \"c\", \"dicestream_editingID\"),\n                    dicestream)\n\n            else\n                Octopus.LOG.error(\"输入值不合法\")\n            end\n            ScriptArgs = getVar(args, \"c\", \"dicestream_editingID\")\n            RunScript(\"dicestream_set\", SCRIPTS)\n\n        end,\n        dicestream_new = function()\n            if Octopus.logic.length(Octopus.Data.get_folder(\"DiceStreamLibrary\")) < 50 then\n                Octopus.Data.save(\"DiceStreamLibrary\",\n                    Octopus.logic.length(Octopus.Data.get_folder(\"DiceStreamLibrary\")) + 1,\n                    Utils.DiceRoller.DiceStream.template)\n\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.SUCCESS)\n            else\n                Octopus.LOG.error(\"判定流上限为50个！\")\n            end\n            Octopus.GUI.Menu.open(MenuLibrary.DiceRoller_Dicestream_Main())\n        end,\n        dicestream_delete = function()\n            Octopus.Data.save(\"DiceStreamLibrary\",\n                ScriptArgs, nil\n            )\n            Octopus.Data.save(\n                \"DiceStreamLibrary\"\n                , nil, Octopus.logic.sortkeybynumber(Octopus.Data.get_folder(\"DiceStreamLibrary\"))\n            )\n            Octopus.GUI.Menu.open(MenuLibrary.DiceRoller_Dicestream_Main())\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.SUCCESS)\n            effect(\"text\", args, \"已为您删除此判定流！\", \"3\")\n        end,\n        dicesender_change = function()\n            local sender_info = Octopus.Data.get_folder(\"Diceroller_sender_info\")\n            if ScriptArgs == \"judge_mode\" or\n                ScriptArgs == \"sender_mode\" or\n                ScriptArgs == \"team_mode\" then\n                if ScriptArgs == \"judge_mode\" then\n                    if sender_info[ScriptArgs] == \"solo\" then\n                        sender_info[ScriptArgs] = \"team\"\n                    else\n                        sender_info[ScriptArgs] = \"solo\"\n                    end\n                end\n                if ScriptArgs == \"sender_mode\" then\n                    if sender_info[ScriptArgs] == \"online\" then\n                        sender_info[ScriptArgs] = \"offline\"\n                    else\n                        sender_info[ScriptArgs] = \"online\"\n                    end\n                end\n                if ScriptArgs == \"team_mode\" then\n                    if sender_info[ScriptArgs] == \"allpass\" then\n                        sender_info[ScriptArgs] = \"sum\"\n                    else\n                        sender_info[ScriptArgs] = \"allpass\"\n                    end\n                end\n                Octopus.Data.save(\"Diceroller_sender_info\", nil, sender_info)\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n                Octopus.GUI.Menu.open(MenuLibrary.Diceroller_sender_main())\n            elseif ScriptArgs == \"dicestream_id\" then\n                local obj = {}\n                local dicestreams = Octopus.Data.get_folder(\"DiceStreamLibrary\")\n\n                for i, v in pairs(dicestreams) do\n\n                    obj[i] = {}\n\n                    obj[i][\"text\"] = string.format(\"%s：%s,需求:%s,奖励%s,%sd%s,\",\n                        i,\n                        v['judge_type'],\n                        v['needed_point'],\n                        v[\"award_point\"],\n                        v[\"dice_num\"],\n                        v[\"dice_surface\"]\n                    )\n                    obj[i][\"scriptname\"] = \"dicesender_change_streamid\"\n                    obj[i][\"scriptargs\"] = i\n\n                end\n\n                Octopus.GUI.Menu.Builder.choose2(obj, \"判定流\", \"diceroller_judge_menu\", 10)\n\n            end\n        end,\n        dicesender_change_streamid = function()\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n            local sender_info = Octopus.Data.get_folder(\"Diceroller_sender_info\")\n            sender_info[\"dicestream_id\"] = ScriptArgs\n            Octopus.Data.save(\"Diceroller_sender_info\", nil, sender_info)\n            Octopus.GUI.Menu.open(MenuLibrary.Diceroller_sender_main())\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.SUCCESS)\n        end,\n        diceroller_judge_menu = function()\n            if getVar(args, \"c\", \"TeamJudging\") ~= 'TRUE' then\n                if Octopus.logic.length(Octopus.Data.get_folder(\"DiceStreamLibrary\")) > 0 then\n                    Octopus.GUI.Menu.open(MenuLibrary.Diceroller_sender_main())\n                    Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DIG)\n                else\n                    Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.ERROR)\n                    Octopus.LOG.error(\"你必须先创建一个判定流才能这么做。已为您跳转！\")\n                    Octopus.RunScript(\"diceroller_dicestream_menu\", SCRIPTS)\n                end\n            else\n                Octopus.GUI.Menu.open(MenuLibrary.Diceroller_sender_waiting2())\n            end\n        end,\n        diceroller_sender_send = function()\n            local sender_info = Octopus.Data.get_folder(\"Diceroller_sender_info\")\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.MACHINE)\n            local judge_info = Octopus.Data.get_folder(\"DiceStreamLibrary\")[sender_info[\"dicestream_id\"]]\n            if sender_info[\"judge_mode\"] == \"solo\" then\n                if op(\"unit_is_player\", args, \"target\") == true then\n                    if sender_info['sender_mode'] == \"online\" then\n                        if op(\"unit_name\", args, \"target\") ~= op(\"unit_name\", args, \"player\") then\n                            judge_info[\"sender\"] = op(\"unit_name\", args, \"player\")\n                            Octopus.Data.send(\"diceroller_received\", judge_info)\n                            local targetplayer = op(\"unit_name\", args, \"target\")\n                            setVar(args, \"c\", \"sender_targetplayer\", targetplayer)\n                            Octopus.GUI.Menu.open(MenuLibrary.Diceroller_sender_waiting1())\n                            effect(\"text\", args, \"已发送判定到\" .. op(\"unit_name\", args, \"target\"), \"3\")\n\n                        else\n                            Octopus.LOG.error(\"你不能发送判定到自己！\")\n                            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.ERROR)\n                        end\n                    elseif sender_info['sender_mode'] == \"offline\" then\n                        local l = Octopus.Listener.new(\"OnMessage_system\", \"dice_feedback_solo_offline\",\n                            \"WaitingDiceFeedback\")\n                        Octopus.Listener.open(l)\n                        local targetplayer = op(\"unit_name\", args, \"target\")\n                        setVar(args, \"c\", \"sender_targetplayer\", targetplayer)\n                        setVar(args, \"c\", \"sender_dicenum\", judge_info[\"dice_num\"])\n\n                        Octopus.GUI.Menu.open(MenuLibrary.Diceroller_sender_waiting1())\n                        effect(\"speech_player\", args, \"/e\", (\"【OOC】要求%s进行判定！（请输入'/roll %s'，可输入%s次）\"\n                            ):format(\n                                targetplayer,\n                                judge_info[\"dice_surface\"],\n                                judge_info[\"dice_num\"]\n                            ))\n                    end\n                else\n                    Octopus.LOG.error(\"你必须先选中一个玩家！\")\n                    Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.ERROR)\n                end\n\n            elseif sender_info[\"judge_mode\"] == \"team\" then\n                Octopus.Data.save(\"temp_results\", nil, {})\n                Octopus.Data.save(\"temp_results_final\", nil, {})\n                if sender_info[\"team_mode\"] == \"allpass\" then\n                    local l = Octopus.Listener.new(\"OnMessage_system\", \"dice_feedback_team\",\n                        \"WaitingDiceFeedback\")\n                    Octopus.Listener.open(l)\n                    Octopus.GUI.Menu.open(MenuLibrary.Diceroller_sender_waiting2())\n                    effect(\"speech_player\", args, \"/e\", (\"正在进行群体判定（全体通过模式）！请需要参与的玩家输入‘/roll %s’掷骰！\"\n                        ):format(\n                            judge_info[\"dice_surface\"]\n                        ))\n                    effect(\"text\", args, \"c\", \"开始群体判定！\")\n                    setVar(args, \"c\", \"TeamJudging\", \"TRUE\")\n\n\n                elseif sender_info[\"team_mode\"] == \"sum\" then\n                    local l = Octopus.Listener.new(\"OnMessage_system\", \"dice_feedback_team\",\n                        \"WaitingDiceFeedback\")\n                    Octopus.Listener.open(l)\n                    Octopus.GUI.Menu.open(MenuLibrary.Diceroller_sender_waiting2())\n                    effect(\"speech_player\", args, \"/e\", (\"正在进行群体判定（总和模式）！请需要参与的玩家输入‘/roll %s’掷骰！\"\n                        ):format(\n                            judge_info[\"dice_surface\"]\n                        ))\n                    setVar(args, \"c\", \"TeamJudging\", \"TRUE\")\n                    effect(\"text\", args, \"c\", \"开始群体判定！\")\n                end\n\n            end\n\n\n        end,\n        diceroller_received = function()\n            if (Octopus.logic.length(Octopus.Data.get_folder(\"Judging_Info\")) > 0) == false then\n                local judge_info = Octopus.logic.strtotable(ScriptArgs)\n                effect(\"speech_player\", args, \"/e\", (\"【OOC】正在进行判定……\"))\n                Octopus.Data.save(\"Judging_Info\", nil, judge_info)\n                Octopus.GUI.Menu.open(MenuLibrary.Diceroller_judgeGUI())\n            else\n                effect(\"speech_player\", args, \"/e\", (\"【OOC】拒绝判定（已经有一个判定正在进行）\"))\n            end\n\n\n\n        end,\n        diceroller_judge_cancel = function()\n\n            local sender_info = Octopus.Data.get_folder(\"Diceroller_sender_info\")\n            local close_sys_listner = function()\n                Octopus.Listener.close(\"OnMessage_system\", \"WaitingDiceFeedback\")\n            end\n            if sender_info[\"judge_mode\"] == 'solo' then\n\n                if sender_info[\"sender_mode\"] == 'offline' then\n                    close_sys_listner()\n                    setVar(args, \"c\", \"sender_dicenum\", nil)\n                elseif sender_info[\"sender_mode\"] == 'online' then\n                    if op(\"unit_name\", args, \"target\") == getVar(args, \"c\", \"sender_targetplayer\") then\n                        Octopus.Data.send(\"diceroller_roll_cancel\", \"1\")\n                    else\n                        Octopus.LOG.error(\"你必须先选中被你指定过的玩家！\")\n                    end\n\n                end\n                setVar(args, \"c\", \"sender_targetplayer\", nil)\n            elseif sender_info['judge_mode'] == 'team' then\n                close_sys_listner()\n            end\n            effect(\"speech_player\", args, \"/e\", \"取消了判定\")\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.ERROR)\n            effect(\"text\", args, \"已取消\", \"3\")\n            Octopus.GUI.Menu.open(MenuLibrary.DiceRoller_Main)\n        end,\n        dice_feedback_solo = function()\n            if ScriptArgs ~= \"cancel\" then\n                local judge_result = Octopus.logic.strtotable(ScriptArgs)\n                Octopus.GUI.Menu.open(MenuLibrary.Diceroller_judgeGUI_final(judge_result, 'sender'))\n            else\n                effect(\"text\", args, \"判定被取消了。\", \"3\")\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n                Octopus.GUI.Menu.open(MenuLibrary.DiceRoller_Main())\n            end\n\n\n        end,\n        dice_feedback_solo_offline = function()\n            local EventValue = Octopus.Data.eventargs_analysis()\n\n            if EventValue['1'] ~= nil and EventValue['1']:find(\"掷\") ~= nil then\n\n                local info = Utils.DiceRoller.DiceSender.systemmessage_process(EventValue[\"1\"])\n\n                if info[1] == getVar(args, \"c\", \"sender_targetplayer\") then\n\n                    local sender_info = Octopus.Data.get_folder(\"Diceroller_sender_info\")\n                    local dicestream = Octopus.Data.get_folder(\"DiceStreamLibrary\")[sender_info['dicestream_id']]\n                    if tonumber(getVar(args, \"c\", \"sender_point\")) == nil then\n                        setVar(args, \"c\", \"sender_point\", \"0\")\n                    end\n                    if tostring(info[3]) == dicestream['dice_surface'] then\n                        local dicenum = tonumber(getVar(args, \"c\", \"sender_dicenum\"))\n                        if dicenum == 1 then\n                            local judge_result = {}\n                            local getted_point = tonumber(info[2]) + tonumber(getVar(args, \"c\", \"sender_point\"))\n                            local result = \"FALSE\"\n                            local total_point = getted_point + tonumber(dicestream['award_point'])\n                            if total_point > tonumber(dicestream['needed_point']) then\n                                result = \"TRUE\"\n                            elseif total_point == tonumber(dicestream['needed_point']) then\n                                result = \"DRAW\"\n                            end\n                            judge_result['result'] = result\n                            judge_result['total_point'] = total_point\n                            judge_result['point'] = getted_point\n                            Octopus.Listener.close(\"OnMessage_system\", \"WaitingDiceFeedback\")\n                            Octopus.GUI.Menu.open(MenuLibrary.Diceroller_judgeGUI_final(judge_result, 'sender'))\n                        else\n\n                            local getted_point = tonumber(info[2])\n                            local point = tonumber(getVar(args, \"c\", \"sender_point\"))\n                            dicenum = dicenum - 1\n                            point = point + getted_point\n                            setVar(args, \"c\", \"sender_point\", tostring(point))\n                            setVar(args, \"c\", \"sender_dicenum\", tostring(dicenum))\n                            effect(\"speech_player\", args, \"/e\", (\"【OOC】收到一次反馈，还剩%s次\"):format(\n                                tostring(dicenum)\n                            ))\n                        end\n                    end\n                end\n            end\n        end,\n        dice_feedback_team = function()\n            local sender_info = Octopus.Data.get_folder(\"Diceroller_sender_info\")\n            local EventValue = Octopus.Data.eventargs_analysis()\n            local results = Octopus.Data.get_folder(\"temp_results\")\n\n            if EventValue['1'] ~= nil and EventValue['1']:find(\"掷\") ~= nil then\n\n                local dicestream = Octopus.Data.get_folder(\"DiceStreamLibrary\")[sender_info['dicestream_id']]\n                local info = Utils.DiceRoller.DiceSender.systemmessage_process(EventValue['1'])\n                if tostring(info[3]) == dicestream['dice_surface'] then\n\n                    effect(\"text\", args, \"收到了来自 \" .. info[1] .. \" 的结果\")\n                    info[4] = tonumber(info[2]) + tonumber(dicestream['award_point'])\n                    local win = \"FALSE\"\n                    if info[4] > tonumber(dicestream['needed_point']) then\n                        win = \"TRUE\"\n                    elseif info[4] == tonumber(dicestream['needed_point']) then\n                        win = \"DRAW\"\n                    end\n                    info[5] = win\n                    results = Octopus.logic.append(results, info)\n                    Octopus.Data.save(\"temp_results\", nil, results)\n                    Octopus.GUI.Menu.open(MenuLibrary.Diceroller_sender_waiting2())\n\n                end\n            end\n\n        end,\n        dice_feedback_team_end = function()\n            local results = Octopus.Data.get_folder(\"temp_results\")\n            local sender_info = Octopus.Data.get_folder(\"Diceroller_sender_info\")\n            local dicestream = Octopus.Data.get_folder(\"DiceStreamLibrary\")[sender_info['dicestream_id']]\n\n            local sumpoint = 0\n            local sumresult = \"FALSE\"\n            local countplayer = 0\n            local winner = {}\n            local failure = {}\n            local drawer = {}\n            local ranked = {}\n            for i, v in pairs(results) do\n                sumpoint = sumpoint + tonumber(v['4'])\n                countplayer = countplayer + 1\n                if v[\"5\"] == \"TRUE\" then\n                    winner = Octopus.logic.append(winner, v['1'])\n                elseif v['5'] == \"FALSE\" then\n                    failure = Octopus.logic.append(failure, v['1'])\n                elseif v[\"5\"] == \"DRAW\" then\n                    drawer = Octopus.logic.append(drawer, v['1'])\n                end\n\n            end\n            if tonumber(dicestream['needed_point']) < sumpoint then\n                sumresult = \"TRUE\"\n            elseif tonumber(dicestream['needed_point']) == sumpoint then\n                sumpoint = \"DRAW\"\n            end\n            local temp = results\n            local i = 1\n            local n = 1\n            local o = 0\n            local res = {}\n            local bef = {}\n            while i < Octopus.logic.length(temp) do\n                i = i + 1 --the start location of res\n                o = i --the present location of res\n                res = temp[tostring(o)]\n\n                while (o > 1) do --if location > 1\n                    bef = temp[tostring(o - 1)] --get the value before it\n                    if tonumber(res['2']) > tonumber(bef['2']) then\n                        o = o - 1\n                        temp[tostring(o)], temp[tostring(o + 1)] = res, bef --exchange it\n                    else\n                        break\n                    end\n                end\n            end\n            local sorted_result = temp\n\n\n            Octopus.Data.save(\n                \"temp_results_final\",\n                nil,\n                {\n                    results = results,\n                    sumresult = sumresult,\n                    sumpoint = sumpoint,\n                    winner = winner,\n                    failure = failure,\n                    drawer = drawer,\n                    sorted_result = sorted_result\n\n\n                }\n            )\n            setVar(args, \"c\", \"TeamJudging\", \"FALSE\")\n            Octopus.Listener.close(\"OnMessage_system\", \"WaitingDiceFeedback\")\n            Octopus.GUI.Menu.open(MenuLibrary.DiceRoller_sender_team_end({ countplayer, sumresult, winner, failure,\n                drawer, sumpoint, sorted_result }))\n\n        end,\n        diceroller_roll = function()\n            local judge_info = Octopus.Data.get_folder(\"Judging_Info\")\n            if op(\"unit_name\", args, \"target\") == judge_info[\"sender\"] then\n                local dice_surface = judge_info[\"dice_surface\"]\n                local dice_num = tonumber(judge_info[\"dice_num\"])\n                local judge_result = {}\n                judge_result[\"result\"] = \"FALSE\"\n                local function rolladice(sf)\n                    local point = math.random(sf)\n                    return point\n                end\n\n                local total_point = 0\n                while dice_num > 0 do\n                    dice_num = dice_num - 1\n                    total_point = total_point + rolladice(dice_surface)\n                end\n                total_point = total_point + tonumber(judge_info[\"award_point\"])\n                if total_point > tonumber(judge_info[\"needed_point\"]) then\n                    judge_result['result'] = \"TRUE\"\n                elseif total_point == tonumber(judge_info['needed_point']) then\n                    judge_result['result'] = \"DRAW\"\n                end\n                judge_result['point'] = total_point - tonumber(judge_info[\"award_point\"])\n                judge_result['total_point'] = total_point\n                Octopus.Data.send(\"dice_feedback_solo\", judge_result)\n                Octopus.GUI.Menu.open(MenuLibrary.Diceroller_judgeGUI_final(judge_result, 'receiver'))\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.DICE)\n                effect(\"speech_player\", args, \"/e\", (\"【OOC】的判定%s！（需要点数：%s，最终点数%s）\"):\n                    format(\n                        LangTrans.JUDGE_RESULT.DEFAULT[judge_result['result']],\n                        judge_info['needed_point'],\n                        tostring(judge_result['total_point'])\n                    ))\n                Octopus.Data.save(\"Judging_Info\", nil, {})\n            else\n                Octopus.LOG.error(\"你必须先选中你的发送者为目标！\")\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.ERROR)\n\n            end\n        end,\n        diceroller_roll_cancel = function()\n            if op(\"unit_name\", args, \"target\") == judge_info[\"sender\"] then\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.ERROR)\n                effect(\"text\", args, \"已取消\", \"3\")\n                Octopus.Data.send(\"dice_feedback_solo\", \"cancel\")\n                Octopus.Data.save(\"Judging_Info\", nil, {})\n            else\n                Octopus.LOG.error(\"你必须先选中你的发送者为目标！\")\n                Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.ERROR)\n\n            end\n        end,\n        author_word = function()\n            Octopus.GUI.Menu.open(MenuLibrary.Helper())\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.JIHESHI)\n        end\n\n\n\n\n    },\n\n\n\n    onuse = function()\n        local ClickTime = tonumber(getVar(args, \"c\", \"MenuItemClickTime\"))\n        if Octopus.GUI.Menu.Config.MenuItem_UseAble() ~= \"FALSE\" or ClickTime >= 5 then\n            Octopus.GUI.Menu.Config.MenuItem_UseAble(\"FALSE\")\n            Octopus.GUI.Menu.openlatest()\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.MACHINE)\n            setVar(args, \"c\", \"MenuItemClickTime\", 0)\n        elseif ClickTime < 5 then\n            Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.CANCEL)\n            effect(\"text\", args, \"请勿重复打开菜单（连续点击5次可以强制打开）\", \"4\")\n            setVar(args, \"c\", \"MenuItemClickTime\", ClickTime + 1)\n\n        end\n    end,\n\n    init = function()\n\n        Octopus.GUI.Menu.setlatest(MenuLibrary.MAIN)\n        Octopus.Sound.playSoundSelf(Octopus.Assests.SoundLibrary.UI.MACHINE)\n        setVar(args, \"c\", \"MenuItemClickTime\", 0)\n        Octopus.GUI.Menu.openlatest()\n        setVar(args, \"c\", \"temp_input\", \"cancel\")\n        effect(\"run_workflow\", args, \"c\", \"listener.Always\")\n\n    end,\n\n\n\n\n\n\n\n}\n\n\n\n\n\n\n\n\nScriptName = getVar(args, \"c\", \"ScriptName\")\nScriptArgs = getVar(args, \"c\", \"ScriptArgs\")\nScriptFilter = getVar(args, \"c\", \"ScriptFilter\")\n---将被执行的代码\n\nOctopus.RunScript(ScriptName, Octopus.BasicScripts)\nOctopus.RunScript(ScriptName, SCRIPTS)\n\nif winditup ~= \"FALSE\" then\n    Octopus.windup() --clear some variables about scripts\nend"
                },
                id = "script"
              }
            },
            t = "list"
          }
        }
      }
    },
