  ["1027150134pj9La"] = {
    BA = {
      CO = false,
      CR = false,
      CT = false,
      DE = "看起来有点结冰了。",
      DS = 1209.0,
      IC = "inv_letter_07",
      LE = "<可阅读>",
      NA = "普通的信件",
      PA = false,
      PS = 1192.0,
      QA = 4.0,
      QE = false,
      SB = false,
      ST = false,
      UN = false,
      US = true,
      VA = 0.0,
