    BA = {
      CO = false,
      CR = false,
      CT = false,
      DE = "记录着洛丹伦陷落后曾短暂活跃于威尔德的血鹃骑士的名册。奇怪的是，只有3页。\n里面的文字更像是撰写者的控告。",
      DS = 1201.0,
