  ["12041958406dqfn"] = {
    BA = {
      CO = false,
      CR = false,
      CT = false,
      DE = "一卷旧报纸，但是被保存的很好。",
      DS = 1209.0,
      IC = "inv_misc_paperbundle03e",
      NA = "伯拉勒斯日报",
      PA = false,
      PS = 1192.0,
      QA = 1.0,
