  ["1111121750F1YX6"] = {
    BA = {
      CO = false,
      CR = false,
      CT = false,
      DS = 1203.0,
      IC = "inv_misc_book_16",
      NA = "亚历汉德罗的日记",
      PA = false,
      PS = 1186.0,
      QA = 1.0,
      QE = false,
      SB = false,
      ST = false,
      UN = false,
